-- TRENERKI Academy · Zaufany wolontariusz · 2026-11-12
-- Import katalogu, podglądu i 40 lekcji z Zaufany-wolontariusz-Trenerki.html.
-- Pierwszy import przygotowuje kurs do publikacji. Kolejny zachowuje bieżący stan publikacji.
-- Po wdrożeniu strony ustaw published = true dla tego kursu.
begin;

with course_price(slug, price_grosze) as (values ('zaufany-wolontariusz', 0))
insert into public.ta_courses (
  slug, title_pl, title_en, description_pl, category_pl,
  certificate_pl, certificate_en, price_grosze, currency, published
)
select slug, 'Zaufany wolontariusz', 'Trusted Volunteer',
  'Bezpłatny kurs o bezpiecznym wolontariacie. Wybierz rolę, przygotuj pierwszy dyżur, przećwicz reakcję na agresję i naucz się zgłaszać incydenty.',
  'Rodzina i rozwój', 'Zaufany wolontariusz', 'Trusted Volunteer', price_grosze, 'PLN', false
from course_price
on conflict (slug) do update set
  title_pl = excluded.title_pl,
  title_en = excluded.title_en,
  description_pl = excluded.description_pl,
  category_pl = excluded.category_pl,
  certificate_pl = excluded.certificate_pl,
  certificate_en = excluded.certificate_en,
  price_grosze = excluded.price_grosze,
  currency = excluded.currency;

insert into public.ta_course_previews (
  course_slug, curiosity, scenario, outcome_1, outcome_2, outcome_3,
  module_titles, editorial_note, study_minutes, workshop_count
) values (
  'zaufany-wolontariusz',
  'Krótka odprawa przed dyżurem pomaga ustalić, kto przejmuje sprawę, kiedy trzeba przerwać zadanie i jak wezwać wsparcie.',
  'Na pierwszym dyżurze ktoś podnosi głos, a koordynator obsługuje kolejkę. Jak ocenisz ryzyko, postawisz granicę i przekażesz zgłoszenie?',
  'Sprawdzisz ofertę, ustalisz zakres roli i przygotujesz się do pierwszego dyżuru.',
  'Przećwiczysz spokojną rozmowę, bezpieczne wycofanie i wezwanie pomocy w nagłej sytuacji.',
  'Zapiszesz fakty po incydencie, przećwiczysz przekazanie dyżuru i ułożysz plan na 30 dni.',
  $outline$["Wolontariat i jego granice","Motywacja i wybór roli","Formy wolontariatu","Gdzie szukać i jak sprawdzić organizację","Wolontariat w Polsce i porozumienie","Bezpieczeństwo organizacyjne ubezpieczenia i koszty","Nabór rozmowa i dopasowanie","Wdrożenie i pierwszy dyżur","Godność zgoda i sprawczość","Granice i odmawianie","Dane zdjęcia i poufność","Pieniądze dary i konflikty interesów","Słuchanie i prosty język","Praca w zespole i przekazanie dyżuru","Dostępność i równe traktowanie","Konflikt w zespole i informacja zwrotna","Ocena ryzyka przed dyżurem","Wizyty domowe i samotna praca w terenie","Frustracja i pierwsze sygnały eskalacji","Deeskalacja słowna i stawianie granicy","Groźby, atak i wezwanie 112","Nękanie, cyberprzemoc i ochrona danych po incydencie","Gdy krzywdzi członek zespołu lub koordynator","Zgłoszenie incydentu i powrót do działania","Ochrona dzieci przed krzywdzeniem","Wsparcie dorosłych w sytuacji zależności","Pierwsza pomoc psychologiczna","Nagłe zdarzenie i rola wolontariusza","Żywność i pomoc rzeczowa","Wydarzenia, kultura i sport","Seniorzy, szpitale i hospicja","Zwierzęta i środowisko","Mentoring, edukacja i integracja","Pomoc zdalna, kompetencyjna i pracownicza","Klęski żywiołowe i pomoc humanitarna","Wolontariat zagraniczny i programy europejskie","Przeciążenie i przerwa w wolontariacie","Jakość działania i ocena efektów","Przekazanie roli i zakończenie współpracy","Sprawdzian praktyczny i plan na 30 dni"]$outline$::jsonb,
  'Kurs edukacyjny obejmuje 40 działów, 8 kart pracy i sprawdzian sytuacyjny. Dyplom ma charakter wewnętrzny.',
  480, 8
)
on conflict (course_slug) do update set
  curiosity = excluded.curiosity,
  scenario = excluded.scenario,
  outcome_1 = excluded.outcome_1,
  outcome_2 = excluded.outcome_2,
  outcome_3 = excluded.outcome_3,
  module_titles = excluded.module_titles,
  editorial_note = excluded.editorial_note,
  study_minutes = excluded.study_minutes,
  workshop_count = excluded.workshop_count,
  updated_at = now()
where (ta_course_previews.curiosity, ta_course_previews.scenario, ta_course_previews.outcome_1,
       ta_course_previews.outcome_2, ta_course_previews.outcome_3, ta_course_previews.module_titles,
       ta_course_previews.editorial_note, ta_course_previews.study_minutes, ta_course_previews.workshop_count)
  is distinct from
      (excluded.curiosity, excluded.scenario, excluded.outcome_1,
       excluded.outcome_2, excluded.outcome_3, excluded.module_titles,
       excluded.editorial_note, excluded.study_minutes, excluded.workshop_count);

insert into public.ta_lessons (course_slug, lesson_no, title_pl, material)
select 'zaufany-wolontariusz', lesson_no, title_pl, material
from jsonb_to_recordset($volunteer$[
{"lesson_no":0,"title_pl":"Wolontariat i jego granice","material":{"module":1,"sections":[{"heading":"Cel lekcji","text":"Rozpoznasz, kiedy działasz jako wolontariusz i gdzie kończy się Twoja rola."},{"heading":"Najważniejsza zasada","text":"Wolontariat w rozumieniu polskiej ustawy jest dobrowolnym i nieodpłatnym wykonywaniem świadczeń na rzecz uprawnionego podmiotu. Warunki działania uzgadniasz z podmiotem korzystającym ze świadczeń, na przykład fundacją, jednostką samorządową lub podmiotem leczniczym w zakresie działalności leczniczej. Pomoc sąsiedzka ma dużą wartość, a spontaniczne wsparcie bez takiego podmiotu co do zasady daje inną podstawę działania i wymaga własnych ustaleń bezpieczeństwa."},{"heading":"Jak zastosować ją w praktyce","text":"Dobrowolność dotyczy wyboru i uzgodnionego zakresu. Po przyjęciu zmiany ktoś może liczyć na Twoją obecność, więc potwierdź termin i uprzedź zespół o zmianie. Nieodpłatność oznacza brak wynagrodzenia za świadczenie. Rozliczenie uzgodnionych wydatków, szkolenie i zwrot kosztów podróży omów z organizatorem. Przy nowym zadaniu sprawdź, kto je zatwierdza i czy masz przygotowanie."},{"heading":"Co ustalić na dyżurze","text":"Przed pierwszą zmianą zapytaj, dla kogo działasz, co dokładnie robisz i kto decyduje w sytuacji wykraczającej poza Twój zakres. Przy wydawaniu posiłków możesz wskazać skład zgodnie z kartą produktu i poprosić osobę odpowiedzialną o dodatkową weryfikację. O kwalifikowaniu do świadczeń, podawaniu leków czy dopuszczeniu sprzętu rozstrzygają odpowiednio przygotowane osoby według zasad organizatora."},{"heading":"Co zrobić krok po kroku","text":"1. Ustal nazwę podmiotu i osobę koordynującą.\n2. Zapisz cel oraz zadania swojej roli.\n3. Wskaż sytuację wymagającą decyzji specjalisty lub koordynatora.\n4. Potwierdź sposób odwołania dyżuru i przekazania sprawy."},{"heading":"Sytuacja z dyżuru","text":"Firma cateringowa szuka na stałe „wolontariuszy” do pakowania komercyjnych zamówień. Obiecuje referencje i prosi, by zacząć jutro."},{"heading":"Przećwicz","text":"Zapisz po jednym przykładzie wolontariatu formalnego, pomocy sąsiedzkiej i nieodpłatnej czynności dla firmy. Wskaż organizatora i ryzyko."},{"heading":"Sprawdź wynik po wykonaniu","text":"Zapytaj o podmiot korzystający i cel. Jeśli zadanie służy zwykłej sprzedaży firmy, szukaj oferty u uprawnionego organizatora. Powiedz „Szukam wolontariatu przy dystrybucji żywności. Czy robicie to z fundacją lub inną uprawnioną organizacją?”.\n\nKryterium ćwiczenia. Odróżniasz trzy formy, a przy formalnym wolontariacie wskazujesz zakres i kontakt."}],"learning":{"intro":"Rozpoznasz, kiedy działasz jako wolontariusz i gdzie kończy się Twoja rola.","situation":"Firma cateringowa szuka na stałe „wolontariuszy” do pakowania komercyjnych zamówień. Obiecuje referencje i prosi, by zacząć jutro.","example":"Zapytaj o podmiot korzystający i cel. Jeśli zadanie służy zwykłej sprzedaży firmy, szukaj oferty u uprawnionego organizatora. Powiedz „Szukam wolontariatu przy dystrybucji żywności. Czy robicie to z fundacją lub inną uprawnioną organizacją?”.","task":"Zapisz po jednym przykładzie wolontariatu formalnego, pomocy sąsiedzkiej i nieodpłatnej czynności dla firmy. Wskaż organizatora i ryzyko.","question":"Co najlepiej pomoże ocenić, czy oferta jest formalnym wolontariatem?","options":["Obietnica referencji.","Tożsamość podmiotu korzystającego i cel zadań.","Liczba zainteresowanych osób."],"correct":1,"explanation":"Znaczenie mają podmiot, rodzaj działalności i powierzona czynność."},"references":[{"title":"Ustawa o działalności pożytku publicznego i o wolontariacie","url":"https://eli.gov.pl/api/acts/DU/2025/1338/text/U/D20251338Lj.pdf"},{"title":"Korpus Solidarności – Co warto wiedzieć o wolontariacie","url":"https://korpussolidarnosci.gov.pl/Content/pub/broszura_co-wiedziec-o-wolontariacie_2025.pdf"}]}},
{"lesson_no":1,"title_pl":"Motywacja i wybór roli","material":{"module":1,"sections":[{"heading":"Cel lekcji","text":"Dobierzesz rolę do swoich możliwości i rzeczywistej potrzeby organizacji."},{"heading":"Najważniejsza zasada","text":"Możesz szukać kontaktu z ludźmi, rozwijać umiejętność, pomagać w sprawie, która Cię obchodzi, albo dzielić się doświadczeniem. Zacznij od potrzeby organizacji i zapytaj, jaki rezultat ma przynieść pomoc. Chęć rozmów z seniorami jest dobrym punktem wyjścia. Jeśli placówka szuka osoby do telefonicznego potwierdzania terminów, dowiedz się, czy taka rola pozwoli Ci sensownie wykorzystać czas."},{"heading":"Jak zastosować ją w praktyce","text":"Przelicz deklarację na pełny koszt tygodnia. Dwugodzinny dyżur może oznaczać też dojazd, odprawę, przekazanie spraw i czas na odpoczynek. Podaj terminy, które możesz utrzymać w trudniejszym tygodniu. Zastanów się, ile kontaktu z ludźmi, hałasu, wysiłku fizycznego i odpowiedzialności dobrze znosisz. Możesz opisać swoje potrzeby jako warunki pracy, na przykład „potrzebuję zadań, które da się wykonywać na siedząco”."},{"heading":"Co ustalić na dyżurze","text":"Porównaj dwie role według konkretnych informacji. Ustal, kto wdraża i czy możesz zacząć od pojedynczego dyżuru z osobą doświadczoną. Zapytaj, co zrobić, jeśli zakres okaże się zbyt obciążający. Po pierwszych zmianach oceń, czy zadania odpowiadają na potrzeby ludzi i czy masz zasoby, by dalej je rzetelnie wykonywać."},{"heading":"Co zrobić krok po kroku","text":"1. Wybierz sprawę i zapytaj o konkretne potrzeby.\n2. Policz czas wraz z dojazdem i przekazaniem dyżuru.\n3. Porównaj dwa zakresy według obciążenia i wsparcia.\n4. Ustal pierwszy dyżur i termin oceny dopasowania."},{"heading":"Sytuacja z dyżuru","text":"Chcesz działać w schronisku i możesz bywać w dwie soboty w miesiącu. Organizacja potrzebuje wtorkowych dyżurów oraz zdalnych aktualizacji materiałów adopcyjnych."},{"heading":"Przećwicz","text":"Porównaj dwie oferty według celu, czasu, poziomu kontaktu z odbiorcami i sposobu wdrożenia. Zapisz deklarację dostępności."},{"heading":"Sprawdź wynik po wykonaniu","text":"Powiedz „Mogę zadeklarować dwie soboty i jedno zdalne zadanie tygodniowo. Czy potrzebujecie takiego wsparcia?”. Sprawdź, kto zatwierdza opisy oraz skąd wziąć aktualne informacje i zdjęcia.\n\nKryterium ćwiczenia. Podajesz konkretne ograniczenie, możliwy wkład i pytanie o wdrożenie."}],"learning":{"intro":"Dobierzesz rolę do swoich możliwości i rzeczywistej potrzeby organizacji.","situation":"Chcesz działać w schronisku i możesz bywać w dwie soboty w miesiącu. Organizacja potrzebuje wtorkowych dyżurów oraz zdalnych aktualizacji materiałów adopcyjnych.","example":"Powiedz „Mogę zadeklarować dwie soboty i jedno zdalne zadanie tygodniowo. Czy potrzebujecie takiego wsparcia?”. Sprawdź, kto zatwierdza opisy oraz skąd wziąć aktualne informacje i zdjęcia.","task":"Porównaj dwie oferty według celu, czasu, poziomu kontaktu z odbiorcami i sposobu wdrożenia. Zapisz deklarację dostępności.","question":"Jak zadeklarować czas organizacji?","options":["Obiecać pełną dostępność.","Wziąć najbliższe zmiany i później sprawdzić, które uda się utrzymać.","Podać liczbę i terminy dyżurów, które realnie możesz utrzymać."],"correct":2,"explanation":"Przewidywalna deklaracja ułatwia obsadzenie zmian i zapewnienie ciągłości pomocy."},"references":[{"title":"Korpus Solidarności – Co warto wiedzieć o wolontariacie","url":"https://korpussolidarnosci.gov.pl/Content/pub/broszura_co-wiedziec-o-wolontariacie_2025.pdf"},{"title":"Praktyczny poradnik współpracy z wolontariuszami – Fundacja Stocznia","url":"https://stocznia.org.pl/publikacje/praktyczny-poradnik-wspolpracy-z-wolontariuszami/"},{"title":"Klon/Jawor – Kondycja organizacji pozarządowych 2024","url":"https://fakty.ngo.pl/raporty/kondycja-organizacji-pozarzadowych-2024-bkj"}]}},
{"lesson_no":2,"title_pl":"Formy wolontariatu","material":{"module":1,"sections":[{"heading":"Cel lekcji","text":"Porównasz formy według czasu, miejsca, rodzaju zadania i przygotowania."},{"heading":"Najważniejsza zasada","text":"Wolontariat akcyjny obejmuje wydarzenie lub krótki projekt, na przykład pomoc w punkcie informacyjnym maratonu. Wolontariat stały ma powtarzalny rytm, jak cotygodniowy klub seniora. Szkolny lub studencki bywa organizowany przez placówkę, samorząd albo partnera. W wolontariacie pracowniczym dopytaj, kto korzysta ze świadczeń, jak uzgadnia się czas z pracodawcą i jakie zasady obowiązują podczas działania."},{"heading":"Jak zastosować ją w praktyce","text":"Zadania mogą odbywać się na miejscu, zdalnie lub łączyć obie formy. Przykłady to segregowanie darów, wspieranie biblioteki, zorganizowane sprzątanie lasu, aktualizacja opisów adopcyjnych, przygotowanie napisów do filmu i mentoring. W wolontariacie kompetencyjnym wykorzystujesz konkretną umiejętność, na przykład tłumaczenie lub projektowanie. Uzgodnij zakres, weryfikację jakości, dostęp do materiałów i termin oddania."},{"heading":"Co ustalić na dyżurze","text":"Pomoc humanitarna i działania kryzysowe wymagają jasnego przydziału oraz koordynacji. Zacznij od oficjalnego naboru i zadań, do których Cię przeszkolono, na przykład obsługi rejestracji w punkcie pomocy. W programach międzynarodowych, takich jak Europejski Korpus Solidarności, sprawdź aktualne warunki oferty, w tym kryteria wieku, zakres wsparcia, ubezpieczenie, podróż i sposób zgłaszania problemów za granicą."},{"heading":"Co zrobić krok po kroku","text":"1. Wybierz akcję, projekt lub stały rytm.\n2. Ustal, czy pasują Ci zadania na miejscu, zdalne lub łączone.\n3. Porównaj wiek, przygotowanie, kontakt z odbiorcami i wsparcie.\n4. Sprawdź warunki oferty przed wydatkiem lub wyjazdem."},{"heading":"Sytuacja z dyżuru","text":"Po wezbraniu rzeki krąży post, by przyjechać własnym autem po dary. Oficjalny punkt pomocy nie potwierdza takiego wezwania."},{"heading":"Przećwicz","text":"Przyporządkuj trzy role do kategorii czasu, miejsca i kontaktu z odbiorcami. Dopisz po jednym wymaganiu i działaniu koordynatora."},{"heading":"Sprawdź wynik po wykonaniu","text":"Sprawdź komunikat gminy lub organizacji prowadzącej punkt. Zapytaj o przydział, miejsce zgłoszenia i instruktaż. Niezapowiedziany samochód lub niezamówione dary mogą obciążyć punkt.\n\nKryterium ćwiczenia. Rozpoznajesz, że rola może łączyć kilka form. Przy większym ryzyku wskazujesz oficjalny nabór i osobę prowadzącą."}],"learning":{"intro":"Porównasz formy według czasu, miejsca, rodzaju zadania i przygotowania.","situation":"Po wezbraniu rzeki krąży post, by przyjechać własnym autem po dary. Oficjalny punkt pomocy nie potwierdza takiego wezwania.","example":"Sprawdź komunikat gminy lub organizacji prowadzącej punkt. Zapytaj o przydział, miejsce zgłoszenia i instruktaż. Niezapowiedziany samochód lub niezamówione dary mogą obciążyć punkt.","task":"Przyporządkuj trzy role do kategorii czasu, miejsca i kontaktu z odbiorcami. Dopisz po jednym wymaganiu i działaniu koordynatora.","question":"Co zrobić przed dołączeniem do pomocy po powodzi?","options":["Potwierdzić przydział i instrukcję u podmiotu koordynującego.","Przyjechać bez zapowiedzi w miejsce największych szkód.","Zabrać dowolne dary."],"correct":0,"explanation":"Przydział dopasowuje pomoc do rzeczywistej potrzeby i ogranicza ryzyko."},"references":[{"title":"Korpus Solidarności – Co warto wiedzieć o wolontariacie","url":"https://korpussolidarnosci.gov.pl/Content/pub/broszura_co-wiedziec-o-wolontariacie_2025.pdf"},{"title":"Europejski Korpus Solidarności – wolontariat w Europie i poza nią","url":"https://europa.eu/youreurope/citizens/education/volunteering/index_pl.htm"},{"title":"United Nations Volunteers – ścieżki wolontariatu","url":"https://www.unv.org/become-volunteer/"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"}]}},
{"lesson_no":3,"title_pl":"Gdzie szukać i jak sprawdzić organizację","material":{"module":1,"sections":[{"heading":"Cel lekcji","text":"Zweryfikujesz ofertę, organizatora i warunki udostępniania danych."},{"heading":"Najważniejsza zasada","text":"Szukaj w Systemie Obsługi Wolontariatu Korpusu Solidarności, lokalnym centrum wolontariatu, serwisie organizacji, urzędzie gminy, bibliotece lub na tablicach sektora pozarządowego. Wpisy w grupach społecznościowych mogą naprowadzić Cię na ofertę. Porównaj post z komunikatem na oficjalnej stronie organizatora. Jeśli widzisz wyłącznie prywatny numer, znajdź niezależny kontakt i potwierdź nabór."},{"heading":"Jak zastosować ją w praktyce","text":"Zapisz nazwę podmiotu i sprawdź rejestr właściwy dla jego formy. Dla wielu fundacji i stowarzyszeń będzie to Krajowy Rejestr Sądowy. Dla jednostki publicznej pomocne będą jej oficjalna strona i Biuletyn Informacji Publicznej. Ustal, kto podpisuje porozumienie, prowadzi odprawę i do kogo zgłasza się problem z tą osobą. Sprawdź, czy opis oferty podaje cel, czas, zakres i wymagane przygotowanie."},{"heading":"Co ustalić na dyżurze","text":"Dokumenty i dane przekazuj po ustaleniu celu i bezpiecznego kanału. Wiadomość prosząca o szybki przelew na prywatne konto, skan dowodu bez wyjaśnienia albo przekazanie haseł wymaga weryfikacji. Odpowiedzialna osoba wyjaśni, jakie informacje są potrzebne i kto je otrzyma. Przy sprzecznych informacjach odłóż decyzję do momentu uzyskania odpowiedzi przez oficjalny kontakt."},{"heading":"Co zrobić krok po kroku","text":"1. Znajdź ogłoszenie i niezależny oficjalny kontakt.\n2. Sprawdź podmiot w odpowiednim rejestrze lub serwisie.\n3. Poproś o warunki roli, wdrożenia, ubezpieczenia i zgłaszania problemów.\n4. Ustal podstawę oraz bezpieczny kanał przekazania danych."},{"heading":"Sytuacja z dyżuru","text":"Post o zbiórce odsyła do formularza wymagającego skanu dowodu i wpłaty „na identyfikator”. Na stronie fundacji brak informacji o naborze."},{"heading":"Przećwicz","text":"Wybierz ofertę i zapisz nazwę podmiotu, sposób potwierdzenia, rolę, kontakt i trzy informacje do ustalenia."},{"heading":"Sprawdź wynik po wykonaniu","text":"Wstrzymaj formularz i przelew. Użyj kontaktu z oficjalnej strony. Zapytaj o rekrutację, dane i opłaty. Jeśli fundacja nie potwierdzi naboru, przekaż jej link do ogłoszenia.\n\nKryterium ćwiczenia. Wskazujesz dwa punkty weryfikacji i odróżniasz dane do pierwszego kontaktu od wymaganych przy formalnościach."}],"learning":{"intro":"Zweryfikujesz ofertę, organizatora i warunki udostępniania danych.","situation":"Post o zbiórce odsyła do formularza wymagającego skanu dowodu i wpłaty „na identyfikator”. Na stronie fundacji brak informacji o naborze.","example":"Wstrzymaj formularz i przelew. Użyj kontaktu z oficjalnej strony. Zapytaj o rekrutację, dane i opłaty. Jeśli fundacja nie potwierdzi naboru, przekaż jej link do ogłoszenia.","task":"Wybierz ofertę i zapisz nazwę podmiotu, sposób potwierdzenia, rolę, kontakt i trzy informacje do ustalenia.","question":"Co zrobić, gdy ogłoszenie z grupy wymaga pilnego skanu dowodu?","options":["Wysłać skan przez prywatną wiadomość.","Zapytać w komentarzu i wysłać skan po odpowiedzi.","Wstrzymać wysyłkę i zweryfikować nabór przez oficjalny kontakt."],"correct":2,"explanation":"Oficjalny kontakt pozwala sprawdzić cel, osobę i sposób przekazania dokumentu."},"references":[{"title":"System Obsługi Wolontariatu – Narodowy Instytut Wolności","url":"https://niw.gov.pl/nasze-programy/korpus-solidarnosci/system-obslugi-wolontariatu/"},{"title":"Korpus Solidarności – Co warto wiedzieć o wolontariacie","url":"https://korpussolidarnosci.gov.pl/Content/pub/broszura_co-wiedziec-o-wolontariacie_2025.pdf"},{"title":"Jak zaangażować wolontariusza do działań swojej organizacji – ngo.pl","url":"https://poradnik.ngo.pl/jak-zaangazowac-wolontariusza-do-dzialan-swojej-organizacji"},{"title":"Zgłaszanie naruszeń ochrony danych – Urząd Ochrony Danych Osobowych","url":"https://uodo.gov.pl/pl/525/2584"}]}},
{"lesson_no":4,"title_pl":"Wolontariat w Polsce i porozumienie","material":{"module":2,"sections":[{"heading":"Cel lekcji","text":"Rozpoznasz wymagania polskiej ustawy i przydatne warunki porozumienia."},{"heading":"Najważniejsza zasada","text":"W polskiej ustawie podmiot organizujący świadczenia to korzystający. Artykuł 42 określa uprawnione podmioty. Artykuł 43 wskazuje, że kwalifikacje i pozostałe wymagania mają znaczenie, gdy wynikają z odrębnych przepisów. Rola przy dzieciach, w ochronie zdrowia czy w terenie może mieć dodatkowe warunki. Ustal je przed rozpoczęciem z koordynatorem i osobą odpowiedzialną za daną działalność."},{"heading":"Jak zastosować ją w praktyce","text":"Zgodnie z art. 44 uzgodnij zakres, sposób i czas wykonywania świadczeń oraz możliwość rozwiązania porozumienia. Przy okresie dłuższym niż 30 dni porozumienie powinno być sporządzone na piśmie. Przy krótszym okresie, w tym przy dokładnie 30 dniach, możesz zażądać pisemnego potwierdzenia treści porozumienia. Na żądanie korzystający wydaje też pisemne zaświadczenie o wykonanych świadczeniach, w tym o ich zakresie. Pisemna opinia może zostać wydana na Twoją prośbę."},{"heading":"Co ustalić na dyżurze","text":"W praktyce wpisz miejsce lub kanał wykonywania zadań, osobę kontaktową, sposób ustalania zmian, zasady rozliczania kosztów i zgłaszania incydentów. Zapis o zastępstwach powinien wskazywać, komu i kiedy zgłaszasz absencję. Przeczytaj każdą część przed przyjęciem roli. Przy zmianie zakresu poproś o aktualizację ustaleń i zachowaj swoją kopię."},{"heading":"Co zrobić krok po kroku","text":"1. Ustal korzystającego i osobę reprezentującą.\n2. Sprawdź zakres, sposób, czas i zasady rozwiązania.\n3. Potwierdź bezpieczeństwo, koszty i sposób zmiany zakresu.\n4. Zachowaj kopię i w razie potrzeby poproś o zaświadczenie."},{"heading":"Sytuacja z dyżuru","text":"Przyjmujesz sześciotygodniową rolę w domu kultury. Koordynatorka przesyła grafik i planuje spisać porozumienia dopiero po projekcie."},{"heading":"Przećwicz","text":"Napisz robocze porozumienie dla fikcyjnego punktu informacyjnego. Ujmij cztery elementy ustawowe i trzy organizacyjne."},{"heading":"Sprawdź wynik po wykonaniu","text":"Poproś o pisemne porozumienie przed rozpoczęciem. Zaproponuj zakres, terminy, sposób pracy i zasady rozwiązania. Grafik dołącz do ustaleń. Sześć tygodni przekracza 30 dni.\n\nKryterium ćwiczenia. Rozpoznajesz formę pisemną, określasz zakres, sposób, czas i zakończenie, rozróżniasz zaświadczenie oraz opinię."}],"learning":{"intro":"Rozpoznasz wymagania polskiej ustawy i przydatne warunki porozumienia.","situation":"Przyjmujesz sześciotygodniową rolę w domu kultury. Koordynatorka przesyła grafik i planuje spisać porozumienia dopiero po projekcie.","example":"Poproś o pisemne porozumienie przed rozpoczęciem. Zaproponuj zakres, terminy, sposób pracy i zasady rozwiązania. Grafik dołącz do ustaleń. Sześć tygodni przekracza 30 dni.","task":"Napisz robocze porozumienie dla fikcyjnego punktu informacyjnego. Ujmij cztery elementy ustawowe i trzy organizacyjne.","question":"Kiedy ustawa wymaga pisemnego porozumienia ze względu na długość?","options":["Gdy świadczenie trwa dłużej niż 30 dni.","Wyłącznie w pierwszym dniu nowego wolontariusza.","Gdy nabór prowadzono w internecie."],"correct":0,"explanation":"Próg wynosi więcej niż 30 dni, a przy krótszym czasie wolontariusz również może żądać pisemnego potwierdzenia."},"references":[{"title":"Ustawa o działalności pożytku publicznego i o wolontariacie","url":"https://eli.gov.pl/api/acts/DU/2025/1338/text/U/D20251338Lj.pdf"},{"title":"Korpus Solidarności – Co warto wiedzieć o wolontariacie","url":"https://korpussolidarnosci.gov.pl/Content/pub/broszura_co-wiedziec-o-wolontariacie_2025.pdf"},{"title":"Jak zaangażować wolontariusza do działań swojej organizacji – ngo.pl","url":"https://poradnik.ngo.pl/jak-zaangazowac-wolontariusza-do-dzialan-swojej-organizacji"}]}},
{"lesson_no":5,"title_pl":"Bezpieczeństwo organizacyjne ubezpieczenia i koszty","material":{"module":2,"sections":[{"heading":"Cel lekcji","text":"Sprawdzisz ochronę, zasady pokrycia wydatków i reakcję na wypadek."},{"heading":"Najważniejsza zasada","text":"Korzystający informuje o ryzyku i zasadach ochrony oraz zapewnia bezpieczne i higieniczne warunki wykonywania świadczeń. W zależności od zadania i zagrożeń obejmuje to odpowiednie środki ochrony indywidualnej. Dopytaj o ryzyka w miejscu działania, na przykład ruch pojazdów przy rozładunku, pracę z trudnymi materiałami czy samotny kontakt z nieznanymi osobami. Ustal, gdzie zgłasza się wypadek i kto zastępuje koordynatora."},{"heading":"Jak zastosować ją w praktyce","text":"Gdy świadczenie trwa nie dłużej niż 30 dni, korzystający ma obowiązek zapewnić NNW. Przy dłuższym okresie stosuje się przepisy o zaopatrzeniu z tytułu wypadków w szczególnych okolicznościach. Przy porozumieniu na czas nieokreślony poradnik NIW wskazuje na NNW przez pierwsze 30 dni. OC może być zapewnione dodatkowo. Osobno sprawdź zasady dotyczące świadczeń zdrowotnych i warunki delegowania za granicę, zwłaszcza do obszarów dotkniętych konfliktem lub klęską."},{"heading":"Co ustalić na dyżurze","text":"Korzystający pokrywa koszty podróży służbowych i diet na zasadach określonych w przepisach. Wolontariusz może zwolnić go z tego obowiązku w całości lub części w formie pisemnej. Zwrot innych niezbędnych wydatków, w tym typowych kosztów dojazdu na dyżur, ustal przed ich poniesieniem. Zapisz osobę zatwierdzającą, limit, sposób dokumentowania i termin rozliczenia."},{"heading":"Co zrobić krok po kroku","text":"1. Ustal zagrożenia, środki ochrony i drogę zgłoszenia.\n2. Potwierdź okres świadczenia i ochronę.\n3. Ustal akceptację wydatków oraz dokumenty.\n4. Przed samodzielnym zadaniem sprawdź zabezpieczenia."},{"heading":"Sytuacja z dyżuru","text":"Przy dwudniowej akcji masz przenosić skrzynie. Organizator nie podał informacji o NNW ani limicie zakupów i prosi o zakup materiałów z własnych środków."},{"heading":"Przećwicz","text":"Ułóż listę kontrolną dla dwudniowej akcji z żywnością. Uwzględnij ochronę, zagrożenia, kontakt i akceptację zakupu."},{"heading":"Sprawdź wynik po wykonaniu","text":"Poproś przed rozpoczęciem o potwierdzenie NNW i instruktaż. Sprawdź sprzęt i zakres. Zanim zapłacisz, uzyskaj uzgodnienie kosztu i zwrotu lub przekaż zakup osobie odpowiedzialnej.\n\nKryterium ćwiczenia. Poprawnie wskazujesz NNW, odróżniasz je od OC i uzgadniasz koszty przed wydatkiem."}],"learning":{"intro":"Sprawdzisz ochronę, zasady pokrycia wydatków i reakcję na wypadek.","situation":"Przy dwudniowej akcji masz przenosić skrzynie. Organizator nie podał informacji o NNW ani limicie zakupów i prosi o zakup materiałów z własnych środków.","example":"Poproś przed rozpoczęciem o potwierdzenie NNW i instruktaż. Sprawdź sprzęt i zakres. Zanim zapłacisz, uzyskaj uzgodnienie kosztu i zwrotu lub przekaż zakup osobie odpowiedzialnej.","task":"Ułóż listę kontrolną dla dwudniowej akcji z żywnością. Uwzględnij ochronę, zagrożenia, kontakt i akceptację zakupu.","question":"Kto zapewnia NNW przy krajowym wolontariacie zaplanowanym na 30 dni?","options":["Wolontariusz.","Korzystający ze świadczeń.","Osoba pełniąca dyżur jako opiekun zmiany."],"correct":1,"explanation":"Art. 46 ust. 3 określa obowiązek korzystającego dla świadczeń nie dłuższych niż 30 dni."},"references":[{"title":"Ustawa o działalności pożytku publicznego i o wolontariacie","url":"https://eli.gov.pl/api/acts/DU/2025/1338/text/U/D20251338Lj.pdf"},{"title":"Korpus Solidarności – Co warto wiedzieć o wolontariacie","url":"https://korpussolidarnosci.gov.pl/Content/pub/broszura_co-wiedziec-o-wolontariacie_2025.pdf"},{"title":"Jak zaangażować wolontariusza do działań swojej organizacji – ngo.pl","url":"https://poradnik.ngo.pl/jak-zaangazowac-wolontariusza-do-dzialan-swojej-organizacji"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"}]}},
{"lesson_no":6,"title_pl":"Nabór rozmowa i dopasowanie","material":{"module":2,"sections":[{"heading":"Cel lekcji","text":"Przygotujesz rozmowę i sprawdzisz warunki przed przyjęciem roli."},{"heading":"Najważniejsza zasada","text":"Przed rozmową przeczytaj opis organizacji i wybierz dwa przykłady umiejętności związanych z rolą. W logistyce może to być porządkowanie magazynu, a przy zajęciach edukacyjnych prowadzenie prostych instrukcji. Przykład powinien pokazywać czynność i efekt. Przygotuj też pytanie o zadanie, którego jeszcze nie umiesz wykonać samodzielnie i przy którym potrzebujesz wdrożenia."},{"heading":"Jak zastosować ją w praktyce","text":"Na rozmowie ustal częstotliwość, miejsce, oczekiwania na pierwszą zmianę oraz sposób oceny, czy współpraca odpowiada obu stronom. Zapytaj, czy będzie osoba wprowadzająca i kiedy można się z nią skontaktować. Jeżeli organizator wymaga kwalifikacji, dokumentów lub sprawdzeń przed dopuszczeniem, poproś o wyjaśnienie właściwe dla stanowiska oraz o termin i bezpieczny sposób ich przekazania."},{"heading":"Co ustalić na dyżurze","text":"Na koniec podsumuj ustalenia własnymi słowami i poproś o potwierdzenie. Jeśli po spotkaniu okazuje się, że zadanie wymaga regularnych wieczorów, których nie możesz zaoferować, zaproponuj inny wymiar lub inną rolę. Przy organizacji działającej z osobami potrzebującymi stałego wsparcia uczciwa deklaracja czasu zmniejsza ryzyko, że ktoś niespodziewanie przejmie obowiązki."},{"heading":"Co zrobić krok po kroku","text":"1. Przygotuj przykłady i dostępność.\n2. Zapytaj o zadania, pierwszą zmianę i wymagania.\n3. Wskaż czynności wymagające przygotowania.\n4. Zapisz kolejny krok, termin i kontakt."},{"heading":"Sytuacja z dyżuru","text":"Zgłaszasz się do przygotowania materiałów. Na rozmowie dowiadujesz się, że jutro masz samodzielnie prowadzić zajęcia z dziećmi. Zasady ochrony małoletnich nie zostały omówione."},{"heading":"Przećwicz","text":"Napisz zgłoszenie i cztery pytania. Uwzględnij granicę roli oraz wsparcie w pierwszym tygodniu."},{"heading":"Sprawdź wynik po wykonaniu","text":"Powiedz „Zgłosiłem się do przygotowania materiałów. Czy na pierwszym spotkaniu mogę pracować obok osoby prowadzącej?”. Przed przyjęciem innej roli ustal nadzór i wymogi ochrony dzieci.\n\nKryterium ćwiczenia. Deklaracja jest konkretna. Pytania pozwalają ustalić zadania, formalności i sposób uzyskania pomocy."}],"learning":{"intro":"Przygotujesz rozmowę i sprawdzisz warunki przed przyjęciem roli.","situation":"Zgłaszasz się do przygotowania materiałów. Na rozmowie dowiadujesz się, że jutro masz samodzielnie prowadzić zajęcia z dziećmi. Zasady ochrony małoletnich nie zostały omówione.","example":"Powiedz „Zgłosiłem się do przygotowania materiałów. Czy na pierwszym spotkaniu mogę pracować obok osoby prowadzącej?”. Przed przyjęciem innej roli ustal nadzór i wymogi ochrony dzieci.","task":"Napisz zgłoszenie i cztery pytania. Uwzględnij granicę roli oraz wsparcie w pierwszym tygodniu.","question":"Co zrobić, jeśli zakres na rozmowie różni się od ogłoszenia?","options":["Zaakceptować od razu.","Ustalić zakres z odbiorcami już na dyżurze.","Poprosić o opis i sprawdzić warunki nowej roli."],"correct":2,"explanation":"Zmiana zakresu może zmienić wymagania, nadzór i odpowiedzialność."},"references":[{"title":"Korpus Solidarności – Co warto wiedzieć o wolontariacie","url":"https://korpussolidarnosci.gov.pl/Content/pub/broszura_co-wiedziec-o-wolontariacie_2025.pdf"},{"title":"Praktyczny poradnik współpracy z wolontariuszami – Fundacja Stocznia","url":"https://stocznia.org.pl/publikacje/praktyczny-poradnik-wspolpracy-z-wolontariuszami/"},{"title":"Standardy ochrony dzieci – Fundacja Dajemy Dzieciom Siłę","url":"https://standardy.fdds.pl/standardy"}]}},
{"lesson_no":7,"title_pl":"Wdrożenie i pierwszy dyżur","material":{"module":2,"sections":[{"heading":"Cel lekcji","text":"Przejdziesz odprawę, wykonasz zadanie pod opieką i przekażesz stan pracy."},{"heading":"Najważniejsza zasada","text":"Pierwszy dyżur zacznij od odprawy. Ustal, gdzie i z kim pracujesz, czego oczekuje organizator, kto odpowiada za bezpieczeństwo i jakie zmiany zgłaszasz od razu. Poproś o wskazanie wyjścia, miejsca zbiórki, kontaktu do pomocy, kanału komunikacji i zasad zgłaszania wypadku. Przy dyżurze zdalnym sprawdź konta, dostęp do dokumentów i sposób zgłoszenia błędnej wysyłki."},{"heading":"Jak zastosować ją w praktyce","text":"Przy wdrożeniu najpierw obserwuj doświadczoną osobę. Następnie spróbuj jednego zadania pod jej opieką. Na koniec wyjaśnij samodzielnie, co zrobisz w typowej sytuacji i kogo zapytasz przy odstępstwie. Jeśli prowadzisz rejestrację, przećwicz przykładowy wpis na danych testowych oraz przypadek, w którym lista nie zgadza się z dokumentem lub pojawia się osoba bez zapisu."},{"heading":"Co ustalić na dyżurze","text":"Przed wyjściem rozlicz powierzony sprzęt i przekaż sprawy otwarte przez zatwierdzony kanał. Powiedz, które czynności zakończyłeś, co wymaga kolejnego kroku i kiedy trzeba to zrobić. Po dyżurze poproś o krótką informację zwrotną. Zapisz czynność, którą umiesz już wykonać, i rzecz do wyjaśnienia przed następną zmianą."},{"heading":"Co zrobić krok po kroku","text":"1. Zgłoś przybycie i weź udział w odprawie.\n2. Przejdź instruktaż miejsca, narzędzi i kontaktów.\n3. Wykonaj zadanie pod opieką i wyjaśnij reakcję na problem.\n4. Przekaż stan pracy i zapisz kolejny krok."},{"heading":"Sytuacja z dyżuru","text":"Dostajesz listę zgłoszeń na pierwszym dyżurze. Osoba wprowadzająca odchodzi. Pojawiają się osoby bez wpisu i proszą o wpuszczenie."},{"heading":"Przećwicz","text":"Rozpisz sześć punktów odprawy. Przećwicz przekazanie trzech informacji następnej zmianie w minutę."},{"heading":"Sprawdź wynik po wykonaniu","text":"Zadzwoń do ustalonego kontaktu i potwierdź procedurę. Powiedz oczekującym „Sprawdzam możliwość wejścia z koordynatorem”. Zabezpiecz listę przed wglądem z kolejki.\n\nKryterium ćwiczenia. Wskazujesz kontakt, ryzyko, granicę samodzielności i sposób przekazania. Podajesz następny krok oraz termin."}],"learning":{"intro":"Przejdziesz odprawę, wykonasz zadanie pod opieką i przekażesz stan pracy.","situation":"Dostajesz listę zgłoszeń na pierwszym dyżurze. Osoba wprowadzająca odchodzi. Pojawiają się osoby bez wpisu i proszą o wpuszczenie.","example":"Zadzwoń do ustalonego kontaktu i potwierdź procedurę. Powiedz oczekującym „Sprawdzam możliwość wejścia z koordynatorem”. Zabezpiecz listę przed wglądem z kolejki.","task":"Rozpisz sześć punktów odprawy. Przećwicz przekazanie trzech informacji następnej zmianie w minutę.","question":"Co zrobić, gdy sytuacji nie omówiono na odprawie?","options":["Samodzielnie ustanowić nową regułę.","Sprawdzić procedurę z właściwą osobą i powiedzieć oczekującym, co robisz.","Odejść od stanowiska bez przekazania."],"correct":1,"explanation":"Właściwy kontakt zapewnia decyzję i utrzymuje bezpieczną obsługę."},"references":[{"title":"Korpus Solidarności – Co warto wiedzieć o wolontariacie","url":"https://korpussolidarnosci.gov.pl/Content/pub/broszura_co-wiedziec-o-wolontariacie_2025.pdf"},{"title":"Praktyczny poradnik współpracy z wolontariuszami – Fundacja Stocznia","url":"https://stocznia.org.pl/publikacje/praktyczny-poradnik-wspolpracy-z-wolontariuszami/"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"}]}},
{"lesson_no":8,"title_pl":"Godność zgoda i sprawczość","material":{"module":3,"sections":[{"heading":"Cel lekcji","text":"Zaproponujesz pomoc, która chroni prywatność i pozostawia wybór osobie zainteresowanej."},{"heading":"Najważniejsza zasada","text":"Przedstaw się i wyjaśnij, co możesz zaoferować. Zapytaj, jakiej pomocy osoba chce i czy zgadza się na proponowany sposób. Rozdziel czynności wymagające różnych decyzji. Zgoda na wypełnienie formularza nie oznacza zgody na kontakt z rodziną, udostępnienie dokumentu ani publikację relacji. Przed każdą nową czynnością podaj jej cel i pozostaw chwilę na pytania."},{"heading":"Jak zastosować ją w praktyce","text":"Godność widać w prostych decyzjach. Rozmawiaj z osobą, której dotyczy sprawa, również gdy przyszła z opiekunem lub tłumaczem. Pozwól jej określić, co wykona samodzielnie. Zaproponuj krzesło, spokojniejsze miejsce lub odczytanie tekstu. Unikaj głośnego omawiania powodów zgłoszenia. Przekazuj zespołowi tylko informacje potrzebne do kolejnego działania."},{"heading":"Co ustalić na dyżurze","text":"Odmowa lub zmiana zdania może pojawić się na każdym etapie zwykłej pomocy. Potwierdź, co zostało ustalone i zaproponuj kolejną możliwość, jeśli ją masz. Osoby oczekujące wsparcia mogą czuć presję, dlatego zadbaj o swobodę decyzji w sprawie zdjęcia, rozmowy promocyjnej i dodatkowej aktywności. W nagłym zagrożeniu zastosuj procedurę alarmową."},{"heading":"Co zrobić krok po kroku","text":"1. Przedstaw rolę i zapytaj o potrzebę.\n2. Zaproponuj konkretną pomoc i poczekaj na decyzję.\n3. Daj wybór sposobu wsparcia i wyjaśnij kolejny krok.\n4. Uszanuj odmowę i przedstaw dostępną alternatywę."},{"heading":"Sytuacja z dyżuru","text":"Na punkcie wydawania darów koleżanka chce zrobić zdjęcie rodziny. Dorosła osoba mówi „Wolałabym nie, ale jeśli bez zdjęcia nie dostaniemy paczki…”."},{"heading":"Przećwicz","text":"Przećwicz pomoc osobie, która chce sama wypełnić druk i prosi o wyjaśnienie jednego pola. Odegraj jej odmowę dalszej pomocy."},{"heading":"Sprawdź wynik po wykonaniu","text":"Przerwij fotografowanie i powiedz „Odbiór paczki odbywa się na zwykłych zasadach. Zdjęcie jest dobrowolne, więc go nie robimy”. Zaproponuj osobie odpowiedzialnej za dokumentację ujęcie przygotowanych paczek.\n\nKryterium ćwiczenia. Określasz wybór osoby i przerywasz czynność po odmowie. Dalsze opcje podajesz bez nacisku."}],"learning":{"intro":"Zaproponujesz pomoc, która chroni prywatność i pozostawia wybór osobie zainteresowanej.","situation":"Na punkcie wydawania darów koleżanka chce zrobić zdjęcie rodziny. Dorosła osoba mówi „Wolałabym nie, ale jeśli bez zdjęcia nie dostaniemy paczki…”.","example":"Przerwij fotografowanie i powiedz „Odbiór paczki odbywa się na zwykłych zasadach. Zdjęcie jest dobrowolne, więc go nie robimy”. Zaproponuj osobie odpowiedzialnej za dokumentację ujęcie przygotowanych paczek.","task":"Przećwicz pomoc osobie, która chce sama wypełnić druk i prosi o wyjaśnienie jednego pola. Odegraj jej odmowę dalszej pomocy.","question":"Osoba przyjęła pomoc z formularzem, ale odmówiła telefonu do rodziny. Co robisz?","options":["Dzwonię, bo zaakceptowała pomoc.","Szanuję odmowę i sprawdzam, czy przyda się inna forma wsparcia.","Uzależniam dalszą pomoc od zgody na telefon."],"correct":1,"explanation":"Osoba decyduje o kolejnych formach pomocy. Zmiana zakresu wymaga wyjaśnienia i uwzględnienia jej decyzji."},"references":[{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Psychologiczna pierwsza pomoc – WHO i Ministerstwo Zdrowia","url":"https://www.gov.pl/web/zdrowie/psychologiczna-pierwsza-pomoc-przewodnik-dla-pracownikow-w-terenie"},{"title":"Zgłaszanie naruszeń ochrony danych – Urząd Ochrony Danych Osobowych","url":"https://uodo.gov.pl/pl/525/2584"}]}},
{"lesson_no":9,"title_pl":"Granice i odmawianie","material":{"module":3,"sections":[{"heading":"Cel lekcji","text":"Odmówisz przekroczenia zakresu i wskażesz bezpieczny następny krok."},{"heading":"Najważniejsza zasada","text":"Przed dyżurem uzgodnij, które czynności możesz wykonać samodzielnie, które pod nadzorem i które przekazujesz innym. Granice dotyczą też czasu, miejsca i kanału kontaktu. Jeśli rola zakłada korzystanie z telefonu organizacji, prywatny numer może szybko stać się równoległym dyżurem. Ustal, do kogo osoba może zwrócić się po Twojej zmianie i w jakich godzinach."},{"heading":"Jak zastosować ją w praktyce","text":"Krótka odmowa zawiera granicę i następny krok. Możesz powiedzieć „Mogę pomóc skontaktować się z pielęgniarką. Decyzję o leku podejmie osoba z odpowiednimi uprawnieniami”. Osoba może czuć rozczarowanie. Daj jej chwilę i powtórz propozycję w prostych słowach. Powiedz wyłącznie to, co rzeczywiście możesz zrobić lub potwierdzić."},{"heading":"Co ustalić na dyżurze","text":"Przy prośbie wykraczającej poza ustalenia sprawdź, czy ktoś w zespole może przejąć sprawę. Zapisz, komu i kiedy ją przekazałeś. Gdy polecenie jest niebezpieczne lub narusza zasady ochrony, przerwij czynność i powiadom osobę odpowiedzialną. Jeśli problem dotyczy koordynatora, użyj alternatywnej drogi zgłoszenia. Przy bezpośrednim zagrożeniu zastosuj procedurę alarmową i w razie potrzeby wezwij służby."},{"heading":"Co zrobić krok po kroku","text":"1. Nazwij czynność, którą możesz wykonać.\n2. Powiedz, co musi wykonać właściwa osoba.\n3. Ustal bezpieczne przekazanie sprawy.\n4. Zgłoś powtarzającą się presję lub ryzyko."},{"heading":"Sytuacja z dyżuru","text":"Senior prosi, żebyś po dyżurze odebrał kartę bankową, poznał PIN i wypłacił gotówkę. Mówi, że ufa tylko Tobie."},{"heading":"Przećwicz","text":"Na głos odmów prywatnego przewozu, przyjęcia kluczy i dodatkowego dyżuru. Podaj następny krok."},{"heading":"Sprawdź wynik po wykonaniu","text":"Powiedz „Nie przyjmuję kart i kodów. Mogę pomóc skontaktować się z koordynatorką i ustalić bezpieczne wsparcie”. Przekaż sprawę oficjalnym kanałem i sprawdź, czy dotarła.\n\nKryterium ćwiczenia. Krótko wyznaczasz granicę i podajesz możliwy następny krok bez składania obietnic ponad zakres."}],"learning":{"intro":"Odmówisz przekroczenia zakresu i wskażesz bezpieczny następny krok.","situation":"Senior prosi, żebyś po dyżurze odebrał kartę bankową, poznał PIN i wypłacił gotówkę. Mówi, że ufa tylko Tobie.","example":"Powiedz „Nie przyjmuję kart i kodów. Mogę pomóc skontaktować się z koordynatorką i ustalić bezpieczne wsparcie”. Przekaż sprawę oficjalnym kanałem i sprawdź, czy dotarła.","task":"Na głos odmów prywatnego przewozu, przyjęcia kluczy i dodatkowego dyżuru. Podaj następny krok.","question":"Ktoś prosi o czynność poza zakresem i nalega, że to drobiazg. Jak reagujesz?","options":["Robię to pod warunkiem zachowania tajemnicy.","Obiecuję wykonać to później.","Wyjaśniam granicę i kieruję sprawę do właściwej osoby."],"correct":2,"explanation":"Skierowanie pozwala kontynuować wsparcie w granicach przygotowania i bezpieczeństwa."},"references":[{"title":"Ustawa o działalności pożytku publicznego i o wolontariacie","url":"https://eli.gov.pl/api/acts/DU/2025/1338/text/U/D20251338Lj.pdf"},{"title":"Praktyczny poradnik współpracy z wolontariuszami – Fundacja Stocznia","url":"https://stocznia.org.pl/publikacje/praktyczny-poradnik-wspolpracy-z-wolontariuszami/"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"}]}},
{"lesson_no":10,"title_pl":"Dane zdjęcia i poufność","material":{"module":3,"sections":[{"heading":"Cel lekcji","text":"Rozpoznasz dane wymagające ochrony i zgłosisz błędną wysyłkę."},{"heading":"Najważniejsza zasada","text":"Dane osobowe obejmują informacje pozwalające rozpoznać kogoś także pośrednio. Połączenie wieku, małej miejscowości, daty zdarzenia i zdjęcia może wystarczyć mimo braku nazwiska. Informacje o zdrowiu wymagają szczególnej ochrony. Sprawdź, które dane masz prawo otrzymać zgodnie z instrukcjami organizatora, w jakim systemie je zapisujesz i z kim możesz je udostępnić. Używaj zakresu potrzebnego do zadania."},{"heading":"Jak zastosować ją w praktyce","text":"Zasady wykonania zdjęcia i jego publikacji ustal przed wydarzeniem. Zapytaj, kto fotografuje, gdzie trafiają materiały i na jakiej podstawie organizacja może publikować wizerunek. Przy dzieciach uwzględnij standardy ochrony i ich stanowisko. Zgoda na udział w wydarzeniu nie daje automatycznie prawa do publikacji zdjęcia. W razie wątpliwości wstrzymaj publikację i poproś o decyzję upoważnioną osobę."},{"heading":"Co ustalić na dyżurze","text":"Prywatna poczta, chmura, czat i narzędzia AI mogą przetwarzać dane poza zatwierdzonym obiegiem. Korzystaj z kanałów wskazanych przez organizację. Błędną wysyłkę zgłoś niezwłocznie. Podaj czas, kanał, rodzaj danych i krąg potencjalnych odbiorców. Działaj zgodnie z instrukcją ograniczenia dostępu i dokumentacji. Organizacja ocenia dalsze obowiązki."},{"heading":"Co zrobić krok po kroku","text":"1. Ustal cel, zakres danych i zatwierdzony kanał.\n2. Sprawdź zasady zdjęć i publikacji.\n3. Ogranicz dostęp do osób potrzebujących danych do zadania.\n4. Błędną wysyłkę zgłoś od razu ustaloną drogą."},{"heading":"Sytuacja z dyżuru","text":"W czacie wszystkich wolontariuszy pojawia się arkusz z nazwiskami i danymi zdrowotnymi uczestników. Dostrzegasz to po kilku minutach."},{"heading":"Przećwicz","text":"Napisz zgłoszenie fikcyjnego naruszenia i dwa pytania do organizatora przed fotografowaniem wydarzenia."},{"heading":"Sprawdź wynik po wykonaniu","text":"Niezwłocznie zgłoś incydent właściwej osobie i podaj fakty. Nie kopiuj arkusza. Ogranicz dostęp, jeśli masz uprawnienia i tak stanowi procedura, potem postępuj według instrukcji.\n\nKryterium ćwiczenia. Podajesz czas, kanał, rodzaj danych i potencjalnych odbiorców bez kopiowania treści. Odróżniasz wykonanie zdjęcia od publikacji."}],"learning":{"intro":"Rozpoznasz dane wymagające ochrony i zgłosisz błędną wysyłkę.","situation":"W czacie wszystkich wolontariuszy pojawia się arkusz z nazwiskami i danymi zdrowotnymi uczestników. Dostrzegasz to po kilku minutach.","example":"Niezwłocznie zgłoś incydent właściwej osobie i podaj fakty. Nie kopiuj arkusza. Ogranicz dostęp, jeśli masz uprawnienia i tak stanowi procedura, potem postępuj według instrukcji.","task":"Napisz zgłoszenie fikcyjnego naruszenia i dwa pytania do organizatora przed fotografowaniem wydarzenia.","question":"Co zrobić po zauważeniu pliku z danymi w niewłaściwym czacie?","options":["Zgłosić incydent ustaloną drogą i opisać fakty bez kopiowania pliku.","Czekać na reakcję innych.","Przesłać plik szerzej, by ustalić błąd."],"correct":0,"explanation":"Szybkie zgłoszenie umożliwia organizacji ograniczenie skutków i ocenę dalszych obowiązków."},"references":[{"title":"Zgłaszanie naruszeń ochrony danych – Urząd Ochrony Danych Osobowych","url":"https://uodo.gov.pl/pl/525/2584"},{"title":"Standardy ochrony dzieci – Fundacja Dajemy Dzieciom Siłę","url":"https://standardy.fdds.pl/standardy"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"}]}},
{"lesson_no":11,"title_pl":"Pieniądze dary i konflikty interesów","material":{"module":3,"sections":[{"heading":"Cel lekcji","text":"Rozliczysz powierzone środki i ujawnisz okoliczność wpływającą na bezstronność."},{"heading":"Najważniejsza zasada","text":"Zanim odbierzesz pieniądze albo dary, zapytaj, kto może je przyjąć, jak je opisuje i gdzie trafiają. Organizator wskazuje dopuszczone formy wpłaty i sposób rozliczenia. Używaj oficjalnej puszki, konta lub innej metody zatwierdzonej dla zbiórki. Przy gotówce ustal liczenie i przekazanie. Jeżeli procedura wymaga dwóch osób, umów ich obecność przed dyżurem."},{"heading":"Jak zastosować ją w praktyce","text":"Przy rzeczach sprawdź kryteria przyjęcia. Żywność może wymagać określonego przechowywania i weryfikacji terminu przydatności. Przy sprzęcie potrzebny bywa opis stanu i miejsce odkładania rzeczy uszkodzonych. Przekaż dary do właściwego punktu i zapisz wyłącznie dane wymagane procedurą. Wątpliwość skonsultuj przed wydaniem środków lub obiecaniem odbioru."},{"heading":"Co ustalić na dyżurze","text":"Konflikt interesów może wystąpić, gdy relacja lub prywatna korzyść wpływa na przydział pomocy, zakup lub wybór osoby. Powiadom koordynatora i przekaż decyzję innej upoważnionej osobie. Gdy ktoś wręcza osobisty upominek, zapytaj o zasady jego przyjmowania. Działaj według uzgodnionych kryteriów także wtedy, gdy znasz osobę ubiegającą się o wsparcie."},{"heading":"Co zrobić krok po kroku","text":"1. Sprawdź, kto dokumentuje środki i dary.\n2. Użyj oficjalnej formy wpłaty i udokumentuj przekazanie.\n3. Zgłoś rozbieżność bez dopasowywania zapisów do kwot.\n4. Ujawnij relację lub korzyść i przekaż decyzję."},{"heading":"Sytuacja z dyżuru","text":"Znajomy prosi o odłożenie ostatniego grzejnika przed zamknięciem zgłoszeń. Darczyńca chce przesłać pieniądze na Twoje prywatne konto."},{"heading":"Przećwicz","text":"Zapisz wydanie trzech fikcyjnych darów i ułóż wiadomość ujawniającą znajomość z odbiorcą."},{"heading":"Sprawdź wynik po wykonaniu","text":"Podaj kryteria przydziału, ujawnij relację i przekaż decyzję innej osobie. Darczyńcy wskaż oficjalną metodę wpłaty potwierdzoną przez organizację.\n\nKryterium ćwiczenia. W zapisie widać rzecz, ilość, datę i przekazanie. Zgłoszenie umożliwia niezależną decyzję."}],"learning":{"intro":"Rozliczysz powierzone środki i ujawnisz okoliczność wpływającą na bezstronność.","situation":"Znajomy prosi o odłożenie ostatniego grzejnika przed zamknięciem zgłoszeń. Darczyńca chce przesłać pieniądze na Twoje prywatne konto.","example":"Podaj kryteria przydziału, ujawnij relację i przekaż decyzję innej osobie. Darczyńcy wskaż oficjalną metodę wpłaty potwierdzoną przez organizację.","task":"Zapisz wydanie trzech fikcyjnych darów i ułóż wiadomość ujawniającą znajomość z odbiorcą.","question":"Co zrobić, jeśli masz decydować o darze dla osoby, którą prywatnie znasz?","options":["Przydzielić dar w zamian za dyskrecję.","Odrzucić zgłoszenie bez procedury.","Zgłosić relację i przekazać decyzję innej upoważnionej osobie."],"correct":2,"explanation":"Ujawnienie relacji i niezależna decyzja pozwalają stosować wspólne kryteria."},"references":[{"title":"Korpus Solidarności – Co warto wiedzieć o wolontariacie","url":"https://korpussolidarnosci.gov.pl/Content/pub/broszura_co-wiedziec-o-wolontariacie_2025.pdf"},{"title":"Jak zaangażować wolontariusza do działań swojej organizacji – ngo.pl","url":"https://poradnik.ngo.pl/jak-zaangazowac-wolontariusza-do-dzialan-swojej-organizacji"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"}]}},
{"lesson_no":12,"title_pl":"Słuchanie i prosty język","material":{"module":4,"sections":[{"heading":"Cel lekcji","text":"Ustalisz potrzebę i przekażesz zrozumiały następny krok."},{"heading":"Najważniejsza zasada","text":"Zacznij od otwartego pytania, na przykład „Co chce Pani dzisiaj załatwić?”. Pozwól dokończyć odpowiedź, a potem wróć do szczegółu potrzebnego do działania. Podsumuj własnymi słowami „Potrzebuje Pani dowiedzieć się, kiedy odebrać paczkę”. Jeśli źle zrozumiesz, podziękuj za poprawkę i skoryguj ustalenie. W tłumie lub przy wrażliwej sprawie zaproponuj spokojniejsze miejsce zgodne z zasadami bezpieczeństwa."},{"heading":"Jak zastosować ją w praktyce","text":"Używaj krótkich zdań i czasowników pokazujących czynność. Zamiast „procedury kwalifikacyjnej” powiedz „Podejdź do stolika numer dwa. Tam sprawdzą zgłoszenie”. Przy kilku czynnościach podaj kolejność. Dostosuj tempo i kanał. W razie potrzeby użyj instrukcji pisemnej, czytelnego oznaczenia lub uzgodnionego wsparcia językowego."},{"heading":"Co ustalić na dyżurze","text":"Sprawdź zrozumienie pytaniem „Chcę upewnić się, czy jasno to wyjaśniłem. Dokąd pójdzie Pan teraz?”. Gdy nie masz informacji, powiedz, gdzie ją sprawdzisz i kiedy możesz wrócić z odpowiedzią. Przy tłumaczeniu wrażliwych spraw korzystaj z ustalonego wsparcia. Zadbaj o zgodę osoby na udział tłumacza oraz o poufność."},{"heading":"Co zrobić krok po kroku","text":"1. Zadaj otwarte pytanie i wysłuchaj odpowiedzi.\n2. Podsumuj potrzebę i dopuść poprawkę.\n3. Podaj następny krok w dostępnym kanale.\n4. Poproś o powtórzenie działania własnymi słowami."},{"heading":"Sytuacja z dyżuru","text":"Osoba czeka w złej kolejce, słabo zna polski i przytakuje, choć nie wie, dokąd pójść. Za nią rośnie kolejka."},{"heading":"Przećwicz","text":"Przepisz instrukcję „W celu zweryfikowania uprawnienia proszę udać się do stanowiska weryfikacyjnego z wymaganymi dokumentami” na trzy krótkie komunikaty i pytanie."},{"heading":"Sprawdź wynik po wykonaniu","text":"Powiedz „Najpierw stolik dwa”. Wskaż miejsce lub pokaż je na planie i upewnij się, że to pomaga. W razie potrzeby zaoferuj uzgodnione wsparcie językowe z zachowaniem prywatności.\n\nKryterium ćwiczenia. Wskazujesz czynność, miejsce i dokument albo sposób jego ustalenia. Pytanie sprawdzające nie zawstydza."}],"learning":{"intro":"Ustalisz potrzebę i przekażesz zrozumiały następny krok.","situation":"Osoba czeka w złej kolejce, słabo zna polski i przytakuje, choć nie wie, dokąd pójść. Za nią rośnie kolejka.","example":"Powiedz „Najpierw stolik dwa”. Wskaż miejsce lub pokaż je na planie i upewnij się, że to pomaga. W razie potrzeby zaoferuj uzgodnione wsparcie językowe z zachowaniem prywatności.","task":"Przepisz instrukcję „W celu zweryfikowania uprawnienia proszę udać się do stanowiska weryfikacyjnego z wymaganymi dokumentami” na trzy krótkie komunikaty i pytanie.","question":"Który komunikat najłatwiej wykonać?","options":["Proces wymaga dokonania weryfikacji przy właściwym stanowisku.","Podejdź do stolika numer dwa i pokaż numer zgłoszenia.","Zajmij się formalnościami zgodnie z tablicą."],"correct":1,"explanation":"Komunikat podaje działanie, miejsce i informację potrzebną do następnego kroku."},"references":[{"title":"Psychologiczna pierwsza pomoc – WHO i Ministerstwo Zdrowia","url":"https://www.gov.pl/web/zdrowie/psychologiczna-pierwsza-pomoc-przewodnik-dla-pracownikow-w-terenie"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Web Content Accessibility Guidelines 2.2 – W3C","url":"https://www.w3.org/TR/WCAG22/"}]}},
{"lesson_no":13,"title_pl":"Praca w zespole i przekazanie dyżuru","material":{"module":4,"sections":[{"heading":"Cel lekcji","text":"Przekażesz zadanie i uzyskasz potwierdzenie przejęcia."},{"heading":"Najważniejsza zasada","text":"Zespół powinien wiedzieć, kto odpowiada za zadanie, rozstrzyga wyjątki i odbiera zgłoszenia przy nieobecności koordynatora. Na odprawie potwierdź rolę i sposób komunikacji. Osoba kierująca ruchem oraz osoba weryfikująca zgłoszenia mogą pracować obok siebie, lecz odpowiadają za różne decyzje. Przekazuj sprawę do tej, która może wykonać następny krok."},{"heading":"Jak zastosować ją w praktyce","text":"Przekazanie zacznij od stanu zadania i spraw pilnych. Podaj, co się wydarzyło, co już zrobiono, co pozostaje i do kiedy. Nazwij osobę, która ma przejąć temat. Przykład „Przygotowaliśmy 18 paczek. Brakuje dwóch etykiet. Marta sprawdzi listę przed otwarciem o 16.00. Czy potwierdzasz?”. Korzystaj z kanału i danych dopuszczonych przez organizację."},{"heading":"Co ustalić na dyżurze","text":"Jeśli sprawa wpływa na bezpieczeństwo lub ciągłość pomocy, poproś o potwierdzenie przejęcia. Sama wiadomość może pozostawić otwarte zadanie bez osoby odpowiedzialnej. Gdy zastępca się nie zgłasza, skontaktuj się z wyznaczoną osobą dyżurną i ustal dalsze działanie. Na koniec uzupełnij zapis oraz rozlicz klucze, radio, identyfikator i inne powierzone rzeczy."},{"heading":"Co zrobić krok po kroku","text":"1. Podaj stan zmiany oraz sprawy pilne.\n2. Oddziel wykonane działania od następnych kroków i terminów.\n3. Przekaż potrzebne dane właściwym kanałem.\n4. Potwierdź przejęcie sprawy lub skontaktuj się z zastępcą."},{"heading":"Sytuacja z dyżuru","text":"Kończysz dyżur przy wydawaniu posiłków. Trzeba jeszcze zweryfikować dostawę, nowa osoba nie odbiera, punkt zaraz otwiera się dla odbiorców."},{"heading":"Przećwicz","text":"Napisz cztery zdania przekazania. Ujmij otwartą sprawę, termin, osobę przejmującą i kontakt przy braku potwierdzenia."},{"heading":"Sprawdź wynik po wykonaniu","text":"Skontaktuj się z zastępcą koordynatora, podaj stan dostawy i termin otwarcia. Poproś o imienne przejęcie weryfikacji oraz decyzję o wstrzymaniu czynności do czasu jej zakończenia. Zapisz ustalenie.\n\nKryterium ćwiczenia. Wskazujesz czynność, termin i drogę zgłoszenia przeszkody. Wiadomość zawiera potrzebne dane."}],"learning":{"intro":"Przekażesz zadanie i uzyskasz potwierdzenie przejęcia.","situation":"Kończysz dyżur przy wydawaniu posiłków. Trzeba jeszcze zweryfikować dostawę, nowa osoba nie odbiera, punkt zaraz otwiera się dla odbiorców.","example":"Skontaktuj się z zastępcą koordynatora, podaj stan dostawy i termin otwarcia. Poproś o imienne przejęcie weryfikacji oraz decyzję o wstrzymaniu czynności do czasu jej zakończenia. Zapisz ustalenie.","task":"Napisz cztery zdania przekazania. Ujmij otwartą sprawę, termin, osobę przejmującą i kontakt przy braku potwierdzenia.","question":"Który zapis najlepiej zabezpiecza sprawę z terminem?","options":["Na liście są otwarte tematy.","Pisałem na czacie, ktoś pewnie przyjmie.","Marta, potwierdź przejęcie weryfikacji dostawy przed 16.00."],"correct":2,"explanation":"Zapis wskazuje osobę, zadanie, termin i potrzebę potwierdzenia."},"references":[{"title":"Korpus Solidarności – Co warto wiedzieć o wolontariacie","url":"https://korpussolidarnosci.gov.pl/Content/pub/broszura_co-wiedziec-o-wolontariacie_2025.pdf"},{"title":"Praktyczny poradnik współpracy z wolontariuszami – Fundacja Stocznia","url":"https://stocznia.org.pl/publikacje/praktyczny-poradnik-wspolpracy-z-wolontariuszami/"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"}]}},
{"lesson_no":14,"title_pl":"Dostępność i równe traktowanie","material":{"module":4,"sections":[{"heading":"Cel lekcji","text":"Rozpoznasz barierę i zaproponujesz dostosowanie z zachowaniem wyboru osoby."},{"heading":"Najważniejsza zasada","text":"Barierą może być stopień przy wejściu, hałas utrudniający rozmowę, formularz w jednym języku albo nieczytelna informacja o kolejce. Zapytaj, jaki sposób kontaktu lub odbioru będzie wygodny. Powiedz, co możesz zaoferować. Przed akcją uzgodnij z zespołem dostępne wejście, punkt odpoczynku, sposób wezwania pomocy i zasady ewakuacji osób potrzebujących wsparcia."},{"heading":"Jak zastosować ją w praktyce","text":"Równe traktowanie wymaga przejrzystych kryteriów i możliwości skorzystania z procesu. Odczytanie dokumentu, krzesło lub dostępna kolejka mogą usunąć barierę przy zachowaniu tych samych warunków przydziału pomocy. Pytaj o użyteczne dostosowanie. Osoba może potrzebować kontaktu pisemnego, choć wcześniej swobodnie rozmawiała, albo samodzielnie korzystać ze sprzętu wspierającego."},{"heading":"Co ustalić na dyżurze","text":"Rozmawiaj bezpośrednio z zainteresowaną osobą. Poproś o zgodę przed dotknięciem jej lub sprzętu. W komunikacji cyfrowej sprawdź opisy zdjęć informacyjnych, czytelność i obsługę bez myszy. Przy zgłoszeniu bariery odnotuj ją bez zbędnych danych o zdrowiu. Poproś zespół o wskazanie osoby odpowiedzialnej i terminu zmiany."},{"heading":"Co zrobić krok po kroku","text":"1. Zapytaj, jaka forma wsparcia odpowiada osobie.\n2. Zaoferuj rozwiązanie i pozostaw wybór.\n3. Zachowaj wspólne kryteria dostępu.\n4. Zgłoś barierę i możliwe rozwiązanie."},{"heading":"Sytuacja z dyżuru","text":"Osoba korzystająca z wózka chce odebrać paczkę. Wejście ma schody. Ktoś proponuje wniesienie jej razem z wózkiem bez wcześniejszego uzgodnienia."},{"heading":"Przećwicz","text":"Wybierz miejsce lub formularz. Wskaż trzy bariery, rozwiązanie na dziś i zmianę wymagającą decyzji organizatora."},{"heading":"Sprawdź wynik po wykonaniu","text":"Zapytaj osobę, jak chce odebrać paczkę. Zaproponuj dostępne wejście lub uzgodnij przeniesienie obsługi. Zgłoś barierę, aby kolejne osoby mogły skorzystać z dostępnej trasy.\n\nKryterium ćwiczenia. Rozwiązanie zachowuje wybór osoby i ma wskazanego właściciela."}],"learning":{"intro":"Rozpoznasz barierę i zaproponujesz dostosowanie z zachowaniem wyboru osoby.","situation":"Osoba korzystająca z wózka chce odebrać paczkę. Wejście ma schody. Ktoś proponuje wniesienie jej razem z wózkiem bez wcześniejszego uzgodnienia.","example":"Zapytaj osobę, jak chce odebrać paczkę. Zaproponuj dostępne wejście lub uzgodnij przeniesienie obsługi. Zgłoś barierę, aby kolejne osoby mogły skorzystać z dostępnej trasy.","task":"Wybierz miejsce lub formularz. Wskaż trzy bariery, rozwiązanie na dziś i zmianę wymagającą decyzji organizatora.","question":"Jak zacząć, gdy osoba napotyka barierę przy odbiorze?","options":["Zapytać, co ułatwi odbiór, i podać opcje.","Wybrać sposób pomocy bez rozmowy.","Zapytać wyłącznie osobę towarzyszącą."],"correct":0,"explanation":"Pytanie dopasowuje pomoc i pozostawia zainteresowanej osobie wpływ."},"references":[{"title":"Web Content Accessibility Guidelines 2.2 – W3C","url":"https://www.w3.org/TR/WCAG22/"},{"title":"Psychologiczna pierwsza pomoc – WHO i Ministerstwo Zdrowia","url":"https://www.gov.pl/web/zdrowie/psychologiczna-pierwsza-pomoc-przewodnik-dla-pracownikow-w-terenie"},{"title":"Praktyczny poradnik współpracy z wolontariuszami – Fundacja Stocznia","url":"https://stocznia.org.pl/publikacje/praktyczny-poradnik-wspolpracy-z-wolontariuszami/"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"}]}},
{"lesson_no":15,"title_pl":"Konflikt w zespole i informacja zwrotna","material":{"module":4,"sections":[{"heading":"Cel lekcji","text":"Rozróżnisz zwykły spór od sytuacji wymagającej zgłoszenia."},{"heading":"Najważniejsza zasada","text":"Spory pojawiają się przy niejasnym podziale pracy i różnych oczekiwaniach. Opisz obserwację, wpływ na zadanie i konkretną prośbę. Możesz powiedzieć „Dziś dwa razy przeniesiono paczki bez informacji dla wydających. To wydłużyło kolejkę. Czy zapisujemy zmianę miejsca w arkuszu dyżuru?”. Zapytaj, czego druga osoba potrzebuje, by to rozwiązanie działało."},{"heading":"Jak zastosować ją w praktyce","text":"Rzeczową uwagę przekaż w spokojnym miejscu i czasie, jeśli rozmowa jest bezpieczna. Przy pilnym ryzyku przerwij czynność krótkim komunikatem i zawołaj właściwą osobę. Po rozmowie uzgodnij jedną zmianę, osobę odpowiedzialną i termin sprawdzenia. Gdy problem powraca, przekaż koordynatorowi fakty i dotychczasowe ustalenia, by mógł zmienić organizację."},{"heading":"Co ustalić na dyżurze","text":"Groźby, nękanie, dyskryminacja i odwet wymagają uruchomienia drogi zgłoszenia. Zanotuj zdarzenia i zachowaj dokumentację zgodnie z zasadami organizacji. Jeśli osoba przyjmująca zgłoszenie uczestniczy w problemie, użyj kontaktu alternatywnego. Przy bezpośrednim zagrożeniu wybierz bezpieczne miejsce i wezwij potrzebną pomoc. Rozmowa wyjaśniająca może odbyć się później pod opieką osób odpowiedzialnych."},{"heading":"Co zrobić krok po kroku","text":"1. Oceń, czy sprawa wymaga zgłoszenia lub pilnej reakcji.\n2. Przy zwykłym sporze opisz fakt, skutek i prośbę.\n3. Ustal następny krok i termin sprawdzenia.\n4. Przy groźbie, nękaniu lub odwecie użyj ścieżki zgłoszenia."},{"heading":"Sytuacja z dyżuru","text":"Wolontariusz trzeci raz zmienia grafik bez informacji. Po pytaniu o ustalenia wysyła obraźliwe wiadomości i grozi, że usunie Cię z zespołu."},{"heading":"Przećwicz","text":"Napisz komunikat o spóźnionym grafiku według układu fakt, wpływ i prośba. Podaj dwa przypadki wymagające zgłoszenia."},{"heading":"Sprawdź wynik po wykonaniu","text":"Zakończ prywatną wymianę. Zachowaj wiadomości zgodnie z zasadami i zgłoś sprawę odpowiedzialnej osobie lub zastępcy. Podaj daty, zachowania i skutek. Poproś o potwierdzenie i sposób bezpiecznego kontaktu.\n\nKryterium ćwiczenia. Podajesz obserwowalny fakt i wykonalną prośbę. Groźby i nękanie kierujesz na właściwą ścieżkę."}],"learning":{"intro":"Rozróżnisz zwykły spór od sytuacji wymagającej zgłoszenia.","situation":"Wolontariusz trzeci raz zmienia grafik bez informacji. Po pytaniu o ustalenia wysyła obraźliwe wiadomości i grozi, że usunie Cię z zespołu.","example":"Zakończ prywatną wymianę. Zachowaj wiadomości zgodnie z zasadami i zgłoś sprawę odpowiedzialnej osobie lub zastępcy. Podaj daty, zachowania i skutek. Poproś o potwierdzenie i sposób bezpiecznego kontaktu.","task":"Napisz komunikat o spóźnionym grafiku według układu fakt, wpływ i prośba. Podaj dwa przypadki wymagające zgłoszenia.","question":"Jak postąpić, gdy spór o grafik przechodzi w powtarzające się groźby?","options":["Zaproponować spotkanie sam na sam w odosobnieniu.","Zakończyć wymianę i zgłosić fakty właściwym kanałem.","Odpowiedzieć ostrzej, aby druga osoba zrozumiała granicę."],"correct":1,"explanation":"Groźby wymagają reakcji organizacyjnej. Bezpośrednie zagrożenie może też wymagać pomocy alarmowej."},"references":[{"title":"Praktyczny poradnik współpracy z wolontariuszami – Fundacja Stocznia","url":"https://stocznia.org.pl/publikacje/praktyczny-poradnik-wspolpracy-z-wolontariuszami/"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Agresja w pracy – porady dla osób wykonujących zadania, HSE","url":"https://www.hse.gov.uk/violence/worker/index.htm"}]}},
{"lesson_no":16,"title_pl":"Ocena ryzyka przed dyżurem","material":{"module":5,"sections":[{"heading":"Cel lekcji","text":"Rozpoznasz zagrożenia i ustalisz, co musi się zmienić przed rozpoczęciem zadania."},{"heading":"Najważniejsza zasada","text":"Przed dyżurem zastanów się, co może się wydarzyć i kogo to dotknie. Zagrożenie zależy od miejsca, zadania i dostępnego wsparcia. W punkcie wydawania żywności kolejka może wejść na jezdnię. Podczas zbiórki po zmroku część zespołu może zostać bez kontaktu. Przy pracy online ktoś może omyłkowo udostępnić listę uczestników. Spisz konkretne sytuacje i zacznij od tych, które mogłyby spowodować poważną szkodę."},{"heading":"Jak zastosować ją w praktyce","text":"Dla każdego zagrożenia uzgodnij z koordynatorem jedno zabezpieczenie, osobę odpowiedzialną i moment sprawdzenia. Na przykład zmieńcie ustawienie stanowiska, wyznaczcie osobę do kierowania kolejką i przejdźcie drogę wyjścia przed otwarciem. Sprawdź, kto odbierze telefon, gdzie macie się zebrać po przerwaniu dyżuru i do kogo zgłosić problem. Gdy zabezpieczenia brakuje, ustal zmianę zadania, miejsca lub obsady przed startem."},{"heading":"Co ustalić na dyżurze","text":"Oceniaj warunki także w trakcie dyżuru. Nasilenie tłoku, awaria oświetlenia albo odejście osoby do asekuracji mogą zmienić wcześniejszą decyzję. Ustal próg przerwania pracy, który każdy w zespole rozpozna, na przykład zastawione wyjście lub utratę łączności. Powiadom zespół o przerwaniu i wróć do zadania po przywróceniu uzgodnionych warunków."},{"heading":"Co zrobić krok po kroku","text":"1. Wskaż zdarzenie, które mogłoby wyrządzić krzywdę, i ustal, kogo dotyczy.\n2. Wybierz zabezpieczenie i sprawdź, kto odpowiada za jego przygotowanie.\n3. Ustal próg przerwania pracy, kontakt awaryjny i miejsce zbiórki.\n4. Sprawdź zabezpieczenia przed startem i ponownie po zmianie warunków."},{"heading":"Sytuacja z dyżuru","text":"Tuż przed otwarciem punktu dystrybucji ktoś stawia wózki z darami w przejściu ewakuacyjnym. Na zewnątrz czekają osoby, które przyszły dużo wcześniej."},{"heading":"Przećwicz","text":"Dla wybranego miejsca przygotuj kartę dyżuru z trzema zagrożeniami, zabezpieczeniami, osobami odpowiedzialnymi i progami przerwania."},{"heading":"Sprawdź wynik po wykonaniu","text":"Powiedz zespołowi, że punkt ruszy po udrożnieniu przejścia i sprawdzeniu go przez osobę odpowiedzialną. Poproś wyznaczoną osobę o podanie aktualnej informacji kolejce.\n\nKryterium ćwiczenia. Każde zagrożenie ma wskazane działanie i moment sprawdzenia. Próg opisuje obserwowalne zdarzenie, a zespół wie, kogo zawiadomić."}],"learning":{"intro":"Rozpoznasz zagrożenia i ustalisz, co musi się zmienić przed rozpoczęciem zadania.","situation":"Tuż przed otwarciem punktu dystrybucji ktoś stawia wózki z darami w przejściu ewakuacyjnym. Na zewnątrz czekają osoby, które przyszły dużo wcześniej.","example":"Powiedz zespołowi, że punkt ruszy po udrożnieniu przejścia i sprawdzeniu go przez osobę odpowiedzialną. Poproś wyznaczoną osobę o podanie aktualnej informacji kolejce.","task":"Dla wybranego miejsca przygotuj kartę dyżuru z trzema zagrożeniami, zabezpieczeniami, osobami odpowiedzialnymi i progami przerwania.","question":"Co robisz po zauważeniu zastawionego wyjścia przed otwarciem?","options":["Wpłuszczam małe grupy i obserwuję przejście.","Przekładam otwarcie do czasu udrożnienia i ponownego sprawdzenia wyjścia.","Czekam, aż kolejka sama się zmniejszy."],"correct":1,"explanation":"Najpierw usuń zagrożenie, sprawdź drogę wyjścia i przekaż informację zespołowi."},"references":[{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Agresja w pracy – porady dla osób wykonujących zadania, HSE","url":"https://www.hse.gov.uk/violence/worker/index.htm"},{"title":"Ustawa o działalności pożytku publicznego i o wolontariacie","url":"https://eli.gov.pl/api/acts/DU/2025/1338/text/U/D20251338Lj.pdf"}]}},
{"lesson_no":17,"title_pl":"Wizyty domowe i samotna praca w terenie","material":{"module":5,"sections":[{"heading":"Cel lekcji","text":"Ułożysz plan kontaktu i wycofania się z wizyty po zmianie warunków."},{"heading":"Najważniejsza zasada","text":"Przed wizytą potwierdź cel, adres i sposób kontaktu z osobą przyjmującą. Ustal z organizacją, kiedy potrzebna jest druga osoba lub wsparcie pracownika. Weź naładowany telefon. Wyznaczony kontakt powinien wiedzieć, gdzie jesteś, kiedy potwierdzisz dotarcie i zakończenie wizyty oraz co zrobi, jeśli się nie odezwiesz. Przetestujcie sposób kontaktu przed wyjściem. Adres i szczegóły wizyty udostępnij tylko osobom, którym są potrzebne."},{"heading":"Jak zastosować ją w praktyce","text":"Po dotarciu sprawdź, czy ustalenia nadal obowiązują. Ktoś może poprosić o zmianę adresu, wprowadzenie do innego mieszkania lub wykonanie czynności poza zakresem. Poproś o wyjaśnienie przed wejściem. Przy niekontrolowanym zwierzęciu, agresywnym zachowaniu albo braku możliwości bezpiecznego wyjścia zakończ próbę wizyty i skontaktuj się z organizacją. Gdy zagrożenie wymaga natychmiastowej interwencji, dzwoń pod 112."},{"heading":"Co ustalić na dyżurze","text":"Omów też drogę powrotu. Wieczorna dostawa lub praca na odludziu mogą wymagać innego punktu spotkania, transportu albo obsady. Po wyjściu wyślij uzgodnione potwierdzenie. Zgłoś zmianę okoliczności, nawet jeśli nikomu nic się nie stało. Zespół może wtedy zmienić następny plan wizyt i zaproponować osobie wspieranej odbiór w punkcie lub spotkanie w parze."},{"heading":"Co zrobić krok po kroku","text":"1. Ustal zakres wizyty, adres, obsadę i warunki wejścia.\n2. Umów potwierdzenie przybycia i zakończenia oraz działanie po braku kontaktu.\n3. Przy zmianie warunków zatrzymaj wizytę i skontaktuj się z organizacją z bezpiecznego miejsca.\n4. Potwierdź zakończenie i przekaż fakty potrzebne przy planowaniu kolejnego kontaktu."},{"heading":"Sytuacja z dyżuru","text":"Dostarczasz zakupy pod ustalony adres. Osoba dzwoni z nieznanego numeru i prosi, abyś wszedł do innego mieszkania. Kontakt dyżurny nie odbiera."},{"heading":"Przećwicz","text":"Odegraj w parze wizytę i brak potwierdzenia. Uzgodnijcie czas, kanał i działanie zapasowe."},{"heading":"Sprawdź wynik po wykonaniu","text":"Pozostań w bezpiecznym miejscu. Wyjaśnij, że zmianę miejsca trzeba potwierdzić z organizacją. Jeżeli nie możesz uzyskać potwierdzenia, odłóż wizytę zgodnie z planem i zapisz próbę kontaktu.\n\nKryterium ćwiczenia. Osoba dyżurna zna adres i czas kontaktu oraz potrafi działać po jego braku. Wolontariusz potrafi przerwać wizytę i przedstawić bezpieczną alternatywę."}],"learning":{"intro":"Ułożysz plan kontaktu i wycofania się z wizyty po zmianie warunków.","situation":"Dostarczasz zakupy pod ustalony adres. Osoba dzwoni z nieznanego numeru i prosi, abyś wszedł do innego mieszkania. Kontakt dyżurny nie odbiera.","example":"Pozostań w bezpiecznym miejscu. Wyjaśnij, że zmianę miejsca trzeba potwierdzić z organizacją. Jeżeli nie możesz uzyskać potwierdzenia, odłóż wizytę zgodnie z planem i zapisz próbę kontaktu.","task":"Odegraj w parze wizytę i brak potwierdzenia. Uzgodnijcie czas, kanał i działanie zapasowe.","question":"Jak reagujesz na prośbę o zmianę adresu, której nie możesz zweryfikować?","options":["Wstrzymuję wizytę i uruchamiam uzgodniony kontakt z organizacją.","Idę pod nowy adres i informuję organizację po wizycie.","Przesyłam adres na ogólny czat uczestników."],"correct":0,"explanation":"Zmiana miejsca bez potwierdzenia podważa plan bezpieczeństwa i utrudnia reakcję osoby dyżurnej."},"references":[{"title":"Praca w pojedynkę – ocena ryzyka, HSE","url":"https://www.hse.gov.uk/lone-working/employer/manage-the-risks-of-working-alone.htm"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"}]}},
{"lesson_no":18,"title_pl":"Frustracja i pierwsze sygnały eskalacji","material":{"module":5,"sections":[{"heading":"Cel lekcji","text":"Rozpoznasz, kiedy włączyć zespół albo zakończyć kontakt."},{"heading":"Najważniejsza zasada","text":"Osoba oczekująca na pomoc może mówić głośno, płakać albo stanowczo domagać się odpowiedzi. Zacznij od tego, co widzisz i słyszysz. „Trzy razy zapytała, kiedy otworzymy punkt” to informacja, z którą zespół może pracować. „Jest niebezpieczna” to wniosek, który wymaga podstaw. Nie zakładaj ryzyka na podstawie wyglądu, pochodzenia, niepełnosprawności czy domniemanej diagnozy."},{"heading":"Jak zastosować ją w praktyce","text":"Zwróć uwagę na zmianę zachowania i sytuacji. Osoba może zacząć podchodzić coraz bliżej, uderzać w przedmioty lub kierować obelgi do konkretnej osoby. Jednocześnie może się zagęszczać tłum, a koordynator odejść od stanowiska. Gdy zauważysz narastanie napięcia, poinformuj zespół wcześnie. Przekaż prostą informację o tym, co da się zrobić, zadbaj o przestrzeń i uzgodnij, kto prowadzi rozmowę."},{"heading":"Co ustalić na dyżurze","text":"Rozmawiaj tak długo, jak jest to bezpieczne. Jeżeli ktoś grozi przemocą, blokuje przejście, próbuje kogoś zaatakować albo istnieje inna nagła groźba wyrządzenia krzywdy, przerwij kontakt i przejdź do procedury bezpieczeństwa. Możesz zakończyć rozmowę wcześniej, gdy tracisz swobodę wycofania lub sytuacja szybko się zmienia. Zgłoś także zdarzenie, które minęło bez obrażeń."},{"heading":"Co zrobić krok po kroku","text":"1. Nazwij zachowanie i zmianę warunków bez oceniania osoby.\n2. Przekaż zespołowi krótką informację i ustal, kto rozmawia.\n3. Jeśli możesz bezpiecznie rozmawiać, podaj jeden możliwy następny krok.\n4. Gdy narasta zagrożenie, przerwij kontakt i użyj ścieżki alarmowej."},{"heading":"Sytuacja z dyżuru","text":"Po opóźnieniu dostawy ktoś podnosi głos. Po chwili uderza dłonią w stół, zbliża się do obsługi i żąda wejścia na zaplecze."},{"heading":"Przećwicz","text":"Zapisz przykładowe obserwacje, które mogą kryć się pod ocenami „ona jest agresywna” i „oni są podejrzani”. Dopisz działanie oraz próg zmiany decyzji."},{"heading":"Sprawdź wynik po wykonaniu","text":"Powiadom zespół, że osoba uderzyła w stół i zbliża się do stanowiska. Zwiększ odległość. Jeżeli rozmowa przestaje być bezpieczna, przerwij ją i uruchom procedurę pomocy.\n\nKryterium ćwiczenia. Opis zawiera zachowanie możliwe do zauważenia przez świadka. Plan obejmuje odległość, wsparcie i moment wycofania."}],"learning":{"intro":"Rozpoznasz, kiedy włączyć zespół albo zakończyć kontakt.","situation":"Po opóźnieniu dostawy ktoś podnosi głos. Po chwili uderza dłonią w stół, zbliża się do obsługi i żąda wejścia na zaplecze.","example":"Powiadom zespół, że osoba uderzyła w stół i zbliża się do stanowiska. Zwiększ odległość. Jeżeli rozmowa przestaje być bezpieczna, przerwij ją i uruchom procedurę pomocy.","task":"Zapisz przykładowe obserwacje, które mogą kryć się pod ocenami „ona jest agresywna” i „oni są podejrzani”. Dopisz działanie oraz próg zmiany decyzji.","question":"Który komunikat daje zespołowi najwięcej użytecznej informacji?","options":["To trudna osoba, więc pewnie zrobi awanturę.","Ten uczestnik zachowuje się podejrzanie.","Uderzył dłonią w stół i zbliża się do stanowiska."],"correct":2,"explanation":"Opis zachowania pomaga ustalić, jakiego wsparcia potrzebujesz."},"references":[{"title":"Agresja w pracy – porady dla osób wykonujących zadania, HSE","url":"https://www.hse.gov.uk/violence/worker/index.htm"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"}]}},
{"lesson_no":19,"title_pl":"Deeskalacja słowna i stawianie granicy","material":{"module":5,"sections":[{"heading":"Cel lekcji","text":"Przećwiczysz odpowiedź na zaczepki i zakończysz kontakt, gdy rozmowa przestaje być bezpieczna."},{"heading":"Najważniejsza zasada","text":"Rozmowa ma sens, gdy możesz zachować odległość, swobodnie wyjść i dostać wsparcie. Stań tak, aby zostawić przestrzeń sobie i drugiej osobie. Mów spokojnie, krótkimi zdaniami i po każdym daj czas na odpowiedź. Pozwól, by jedna osoba z zespołu prowadziła rozmowę. Gdy kilka osób mówi naraz, wyjaśnienie procedury i ustalenie decyzji stają się trudniejsze."},{"heading":"Jak zastosować ją w praktyce","text":"Nazwij sprawę, której dotyczy napięcie. „Rozumiem, że czeka Pan na informację o zgłoszeniu”. Powiedz, co możesz zrobić w tej chwili. „Mogę sprawdzić numer w rejestrze albo poprosić koordynatorkę, żeby podeszła”. Jeżeli zachowanie narusza granicę, powiedz, czego oczekujesz i co zrobisz, gdy zachowanie będzie trwało. „Jeśli dalej będzie mnie Pan wyzywać, zakończę rozmowę i przekażę sprawę koordynatorce”."},{"heading":"Co ustalić na dyżurze","text":"Po postawieniu granicy zrób to, co zapowiedziałeś, jeśli możesz bezpiecznie to wykonać. Unikaj długich wyjaśnień, komentarzy o charakterze drugiej osoby i obietnic, na które nie masz wpływu. Gdy pojawia się bezpośrednie zagrożenie, możesz się wycofać od razu, bez uprzedzenia i bez próby dokończenia rozmowy. Po wycofaniu uruchom procedurę bezpieczeństwa i zgłoś przebieg zdarzenia."},{"heading":"Co zrobić krok po kroku","text":"1. Oceń możliwość wyjścia, zachowaj odległość i zapewnij wsparcie.\n2. Powiedz, jaki problem słyszysz, i zaproponuj jedną lub dwie dostępne opcje.\n3. Nazwij zachowanie, którego oczekujesz, i ustal granicę kontaktu.\n4. Gdy zachowanie trwa lub rośnie zagrożenie, zakończ rozmowę i skorzystaj ze wsparcia."},{"heading":"Sytuacja z dyżuru","text":"Po odmowie wydania dodatkowej paczki uczestniczka zwraca się do Ciebie obraźliwie. Masz wolne przejście, a koordynator jest obok."},{"heading":"Przećwicz","text":"Odegraj w parze krótką rozmowę. Przećwicz nazwanie sprawy, jedną opcję i jedno zdanie stawiające granicę. Uzgodnijcie sygnał kończący ćwiczenie."},{"heading":"Sprawdź wynik po wykonaniu","text":"„Mogę pokazać, jak złożyć prośbę o dodatkową paczkę. Jeśli wyzwiska się powtórzą, zakończę rozmowę i poproszę koordynatora o przejęcie sprawy”. Jeżeli zachowanie trwa, przekaż sprawę. Przy nagłym zagrożeniu wycofaj się od razu.\n\nKryterium ćwiczenia. Wypowiedź opisuje konkretne zachowanie i zawiera wykonalny krok. Reagujesz zgodnie z postawioną granicą."}],"learning":{"intro":"Przećwiczysz odpowiedź na zaczepki i zakończysz kontakt, gdy rozmowa przestaje być bezpieczna.","situation":"Po odmowie wydania dodatkowej paczki uczestniczka zwraca się do Ciebie obraźliwie. Masz wolne przejście, a koordynator jest obok.","example":"„Mogę pokazać, jak złożyć prośbę o dodatkową paczkę. Jeśli wyzwiska się powtórzą, zakończę rozmowę i poproszę koordynatora o przejęcie sprawy”. Jeżeli zachowanie trwa, przekaż sprawę. Przy nagłym zagrożeniu wycofaj się od razu.","task":"Odegraj w parze krótką rozmowę. Przećwicz nazwanie sprawy, jedną opcję i jedno zdanie stawiające granicę. Uzgodnijcie sygnał kończący ćwiczenie.","question":"Które zdanie pomaga postawić wykonalną granicę?","options":["Natychmiast się uspokój, bo wypadniesz z programu.","Obiecuję rozwiązać sprawę, jeśli przestaniesz krzyczeć.","Mogę wyjaśnić zasady. Jeśli wyzwiska będą trwały, zakończę rozmowę i poproszę koordynatora o kontakt."],"correct":2,"explanation":"To zdanie wskazuje konkretne zachowanie, dostępny krok i decyzję, którą możesz wykonać."},"references":[{"title":"Agresja w pracy – porady dla osób wykonujących zadania, HSE","url":"https://www.hse.gov.uk/violence/worker/index.htm"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"}]}},
{"lesson_no":20,"title_pl":"Groźby, atak i wezwanie 112","material":{"module":6,"sections":[{"heading":"Cel lekcji","text":"Przerwiesz kontakt przy bezpośrednim zagrożeniu i przekażesz operatorowi 112 najważniejsze informacje."},{"heading":"Bezpośrednie zagrożenie","text":"Bezpośrednie zagrożenie. Przerwij kontakt. Jeśli to możliwe, oddal się w bezpieczne miejsce. Wezwij 112, gdy sytuacja wymaga natychmiastowej interwencji służb. Nie czekaj na decyzję koordynatora."},{"heading":"Najważniejsza zasada","text":"Atak, bezpośrednia groźba wyrządzenia krzywdy, blokowanie drogi wyjścia w sytuacji zagrożenia albo poważne obrażenia wymagają szybkiej reakcji. Odsuń się, wykorzystaj bezpieczne wyjście, jeśli jest dostępne, i ostrzeż osoby w pobliżu, o ile możesz zrobić to bez narażenia się. Jeżeli ktoś potrzebuje natychmiastowej pomocy służb, dzwoń pod 112. Koordynatora powiadom, gdy możesz to zrobić bez opóźniania wezwania pomocy."},{"heading":"Jak zastosować ją w praktyce","text":"Podaj operatorowi dokładną lokalizację, także wejście lub piętro, jeżeli są ważne. Krótko opisz to, co widzisz, powiedz, czy zagrożenie trwa i ilu osobom trzeba pomóc, jeśli to wiesz. Podaj dane, o które prosi operator. Odpowiadaj na pytania, postępuj zgodnie z instrukcjami, pozostań na linii do zakończenia rozmowy i bądź dostępny na wypadek ponownego kontaktu. Gdy czegoś nie wiesz, powiedz to wprost."},{"heading":"Co ustalić na dyżurze","text":"Zrezygnuj z prób obezwładnienia, odbierania przedmiotów, filmowania i wracania po rzeczy. Jeśli możesz bezpiecznie wskazać służbom miejsce zdarzenia, zrób to według ich wskazówek. Po przekazaniu sytuacji służbom zawiadom organizację i umów bezpieczny sposób dalszego kontaktu. Świadkowie mogą potrzebować wsparcia, podobnie jak osoba bezpośrednio zagrożona."},{"heading":"Co zrobić krok po kroku","text":"1. Przerwij kontakt i przejdź w bezpieczne miejsce, jeśli możesz.\n2. Zadzwoń pod 112, gdy potrzebna jest natychmiastowa interwencja służb.\n3. Podaj lokalizację, rodzaj zagrożenia, stan zdarzenia i dostępne informacje o poszkodowanych.\n4. Postępuj według poleceń operatora i poinformuj organizację, gdy sytuacja na to pozwoli."},{"heading":"Sytuacja z dyżuru","text":"Na wydarzeniu ktoś szarpie osobę przy rejestracji, grozi uderzeniem i blokuje jej drogę. Stoisz przy wyjściu. Koordynatora nie ma obok."},{"heading":"Przećwicz","text":"Przećwicz rozmowę z osobą odgrywającą operatora. Nie wybieraj numeru i użyj wymyślonego adresu."},{"heading":"Sprawdź wynik po wykonaniu","text":"Odsuń się i zadzwoń pod 112. „Jestem w domu kultury przy [adres], wejście od [ulica]. Jedna osoba szarpie pracownika przy rejestracji i blokuje przejście. Zdarzenie trwa”. Odpowiadaj na pytania operatora.\n\nKryterium ćwiczenia. Podajesz lokalizację, trwające zagrożenie i informację o poszkodowanych albo o braku tej wiedzy. Zgłaszasz bez oczekiwania na koordynatora."}],"learning":{"intro":"Przerwiesz kontakt przy bezpośrednim zagrożeniu i przekażesz operatorowi 112 najważniejsze informacje.","situation":"Na wydarzeniu ktoś szarpie osobę przy rejestracji, grozi uderzeniem i blokuje jej drogę. Stoisz przy wyjściu. Koordynatora nie ma obok.","example":"Odsuń się i zadzwoń pod 112. „Jestem w domu kultury przy [adres], wejście od [ulica]. Jedna osoba szarpie pracownika przy rejestracji i blokuje przejście. Zdarzenie trwa”. Odpowiadaj na pytania operatora.","task":"Przećwicz rozmowę z osobą odgrywającą operatora. Nie wybieraj numeru i użyj wymyślonego adresu.","question":"Co robisz, gdy widzisz trwający atak i możesz zadzwonić z bezpiecznego miejsca?","options":["Dzwonię pod 112 i podaję lokalizację oraz to, co się dzieje.","Szukam koordynatora, żeby zatwierdził wezwanie.","Nagrywam zdarzenie, a potem dzwonię."],"correct":0,"explanation":"Trwający atak wymaga natychmiastowego powiadomienia służb."},"references":[{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"},{"title":"Pierwsza pomoc – Poradnik bezpieczeństwa, Gov.pl","url":"https://www.gov.pl/web/poradnikbezpieczenstwa/pierwsza-pomoc"},{"title":"Agresja w pracy – porady dla osób wykonujących zadania, HSE","url":"https://www.hse.gov.uk/violence/worker/index.htm"}]}},
{"lesson_no":21,"title_pl":"Nękanie, cyberprzemoc i ochrona danych po incydencie","material":{"module":6,"sections":[{"heading":"Cel lekcji","text":"Dobierzesz kanał zgłoszenia do zagrożenia alarmowego, nękania lub incydentu cyfrowego."},{"heading":"Najważniejsza zasada","text":"Nękanie może zacząć się na dyżurze i przenieść do wiadomości prywatnych. Przykłady to powtarzające się niechciane kontakty, publikowanie czyjegoś adresu lub śledzenie po zakończeniu zmiany. Jeśli okoliczności wskazują na bezpośrednie zagrożenie i potrzebna jest natychmiastowa interwencja, dzwoń pod 112. W pozostałych przypadkach powiadom organizację odpowiednim kanałem. W sprawie gróźb lub uporczywego nękania możesz skontaktować się z Policją także poza trybem alarmowym."},{"heading":"Jak zastosować ją w praktyce","text":"Jeśli jest bezpiecznie, zachowaj minimum informacji potrzebnych do zgłoszenia. Przydatne bywają daty, nazwa konta, adres wpisu i treść wiadomości. Zadbaj, aby materiały z danymi osób trafiły do uprawnionego odbiorcy uzgodnionym kanałem. Rozważ blokadę konta lub zgłoszenie go platformie zgodnie z planem bezpieczeństwa. Przy próbie wyłudzenia pomiń podejrzany odnośnik. Przekaż sprawę osobie odpowiedzialnej za system i skorzystaj z kanału CERT Polska, gdy dotyczy incydentu cyberbezpieczeństwa."},{"heading":"Co ustalić na dyżurze","text":"Jeżeli ujawniono dane organizacji lub uczestników, zawiadom niezwłocznie osobę wskazaną w procedurze ochrony danych. Wskaż, jakie informacje mogły zostać ujawnione, kiedy i kto miał do nich dostęp. To administrator ocenia, jakie zgłoszenia są wymagane. W razie podejrzenia przejęcia konta organizacyjnego postępuj według instrukcji zespołu IT, a dostęp odzyskuj przez oficjalną stronę lub aplikację."},{"heading":"Co zrobić krok po kroku","text":"1. Oceń pilność zagrożenia i wezwij służby, gdy wymaga natychmiastowej interwencji.\n2. W bezpiecznych warunkach zapisz niezbędne fakty i zachowaj materiał zgodnie z procedurą.\n3. Powiadom właściwy kontakt w organizacji, a w razie potrzeby Policję, platformę lub CERT Polska.\n4. Uzgodnij bezpieczny dalszy kontakt i ograniczenie dostępu do ujawnionych danych."},{"heading":"Sytuacja z dyżuru","text":"Po dyżurze dostajesz wiadomość z Twoim prywatnym adresem i żądaniem przekazania listy uczestników. Nadawca twierdzi, że stoi pod Twoimi drzwiami."},{"heading":"Przećwicz","text":"Dopasuj kanał zgłoszenia do próby wyłudzenia hasła, omyłkowej publikacji listy i groźby pod domem. Pracuj na fikcyjnych danych."},{"heading":"Sprawdź wynik po wykonaniu","text":"Pozostań w bezpiecznym miejscu, nie otwieraj drzwi i zadzwoń pod 112. Opisz wiadomość i powiedz, czego nie możesz potwierdzić. Powiadom organizację. Zachowaj wiadomość w bezpiecznych warunkach i chroń listę uczestników.\n\nKryterium ćwiczenia. Rozróżniasz zgłoszenie alarmowe, incydent cyfrowy i naruszenie ochrony danych. Wskazujesz, jak uniknąć dalszego ujawnienia listy."}],"learning":{"intro":"Dobierzesz kanał zgłoszenia do zagrożenia alarmowego, nękania lub incydentu cyfrowego.","situation":"Po dyżurze dostajesz wiadomość z Twoim prywatnym adresem i żądaniem przekazania listy uczestników. Nadawca twierdzi, że stoi pod Twoimi drzwiami.","example":"Pozostań w bezpiecznym miejscu, nie otwieraj drzwi i zadzwoń pod 112. Opisz wiadomość i powiedz, czego nie możesz potwierdzić. Powiadom organizację. Zachowaj wiadomość w bezpiecznych warunkach i chroń listę uczestników.","task":"Dopasuj kanał zgłoszenia do próby wyłudzenia hasła, omyłkowej publikacji listy i groźby pod domem. Pracuj na fikcyjnych danych.","question":"Co robisz po omyłkowym opublikowaniu listy uczestników w otwartym miejscu?","options":["Rozsyłam zrzut listy, by ostrzec cały zespół.","Zgłaszam od razu osobie odpowiedzialnej za ochronę danych i uzgadniam ograniczenie dostępu.","Czekam do końca tygodnia, żeby ustalić, czy ktoś otworzył listę."],"correct":1,"explanation":"Wczesne zgłoszenie pozwala ograniczyć ujawnienie i umożliwia administratorowi ocenę ryzyka."},"references":[{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"},{"title":"Zgłaszanie naruszeń ochrony danych – Urząd Ochrony Danych Osobowych","url":"https://uodo.gov.pl/pl/525/2584"},{"title":"Jak zgłosić incydent – CERT Polska","url":"https://wiedza.cert.pl/obsluga-incydentow/zgloszenie/incydent-cert-pl/"},{"title":"Zgłaszanie i analiza incydentów przemocy – HSE","url":"https://www.hse.gov.uk/violence/employer/reporting-learning-from-incidents.htm"}]}},
{"lesson_no":22,"title_pl":"Gdy krzywdzi członek zespołu lub koordynator","material":{"module":6,"sections":[{"heading":"Cel lekcji","text":"Dobierzesz sposób zgłoszenia krzywdzącego zachowania, także gdy dotyczy osoby prowadzącej Twój zespół."},{"heading":"Najważniejsza zasada","text":"W zespole mogą zdarzyć się upokarzanie przy innych, komentarze seksualne, naruszanie prywatności albo nacisk na złamanie zasad. Zapisz zachowanie, czas i kontekst. Przy zgłoszeniu pojedynczy, dobrze opisany przypadek jest użyteczną informacją. Jeżeli zachowanie trwa, możesz przerwać kontakt, poprosić o obecność drugiej osoby lub zmienić zadanie. Przy zagrożeniu wymagającym natychmiastowej pomocy służb najpierw zadbaj o bezpieczeństwo i dzwoń pod 112."},{"heading":"Jak zastosować ją w praktyce","text":"Przed pierwszym dyżurem poznaj zwykłą i zapasową drogę zgłoszenia. Jeżeli sprawa dotyczy koordynatora, przejdź do wskazanej osoby odpowiedzialnej za bezpieczeństwo, wyższego przełożonego, zarządu albo innego kontaktu w procedurze. Jeśli organizacja nie udostępnia jasnej ścieżki, sprawdź, kto formalnie odpowiada za jej działanie, albo zwróć się do odpowiednich służb lub specjalistycznej pomocy. Zgłoszenie kieruj do osób uprawnionych, z informacją wystarczającą do podjęcia działania."},{"heading":"Co ustalić na dyżurze","text":"Poproś o potwierdzenie przyjęcia, termin kolejnego kontaktu i informację o tym, jak będzie chroniona Twoja prywatność. Jeżeli po zgłoszeniu pojawiają się groźby albo presja, zapisz i zgłoś także te zdarzenia. Jeśli jesteś świadkiem, zaoferuj osobie poszkodowanej wsparcie i przekaż swoją obserwację zgodnie z procedurą. W sprawach krzywdzenia dziecka obowiązuje ścieżka ochrony małoletnich."},{"heading":"Co zrobić krok po kroku","text":"1. Zadbaj o bezpieczeństwo i przerwij kontakt, gdy to potrzebne.\n2. Zapisz konkretne zachowanie, datę i możliwych świadków.\n3. Wybierz kanał omijający osobę, której dotyczy zgłoszenie.\n4. Poproś o potwierdzenie i uzgodnij ochronę na następny dyżur."},{"heading":"Sytuacja z dyżuru","text":"Koordynator wysyła Ci powtarzające się niechciane komentarze o ciele i proponuje rozmowę na osobności po dyżurze. W regulaminie jest kontakt do członkini zarządu."},{"heading":"Przećwicz","text":"Na fikcyjnym schemacie organizacji wskaż kanał podstawowy, zapasowy i sposób działania w sytuacji alarmowej. Napisz krótką prośbę o przyjęcie sprawy."},{"heading":"Sprawdź wynik po wykonaniu","text":"Zakończ prywatną wymianę, jeśli to bezpieczne. Zachowaj potrzebne wiadomości i przekaż je wskazanej osobie z zarządu z opisem i datami. Poproś o zmianę kontaktu dyżurnego i ustal sposób odpowiedzi.\n\nKryterium ćwiczenia. Zapasowy kanał omija osobę, której dotyczy sprawa. Zgłoszenie zawiera fakty, kontakt zwrotny i konkretną prośbę o ochronę."}],"learning":{"intro":"Dobierzesz sposób zgłoszenia krzywdzącego zachowania, także gdy dotyczy osoby prowadzącej Twój zespół.","situation":"Koordynator wysyła Ci powtarzające się niechciane komentarze o ciele i proponuje rozmowę na osobności po dyżurze. W regulaminie jest kontakt do członkini zarządu.","example":"Zakończ prywatną wymianę, jeśli to bezpieczne. Zachowaj potrzebne wiadomości i przekaż je wskazanej osobie z zarządu z opisem i datami. Poproś o zmianę kontaktu dyżurnego i ustal sposób odpowiedzi.","task":"Na fikcyjnym schemacie organizacji wskaż kanał podstawowy, zapasowy i sposób działania w sytuacji alarmowej. Napisz krótką prośbę o przyjęcie sprawy.","question":"Gdzie zgłosisz niechciane komentarze koordynatora?","options":["W poufnym kanale przeznaczonym do takich zgłoszeń.","Na publicznym profilu organizacji z całą korespondencją.","Koordynatorowi podczas spotkania na osobności."],"correct":0,"explanation":"Kanał zapasowy umożliwia przyjęcie sprawy przez osobę, której zgłoszenie nie dotyczy."},"references":[{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Zgłaszanie i analiza incydentów przemocy – HSE","url":"https://www.hse.gov.uk/violence/employer/reporting-learning-from-incidents.htm"},{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"},{"title":"Vademecum. Wolontariat w szkole zgodnie z prawem – NIW","url":"https://niw.gov.pl/czytelnia/vademecum-wolontariat-w-szkole-zgodnie-z-prawem/"}]}},
{"lesson_no":23,"title_pl":"Zgłoszenie incydentu i powrót do działania","material":{"module":6,"sections":[{"heading":"Cel lekcji","text":"Sporządzisz krótką notatkę i uzgodnisz warunki bezpiecznego powrotu."},{"heading":"Najważniejsza zasada","text":"Po zdarzeniu sprawdź, czy wszystkie zagrożone osoby otrzymały pomoc i kto przejął sprawę. Zgłoś organizacji także sytuację, w której szkody udało się uniknąć. Przykładem jest zablokowanie wyjścia zakończone bez urazu. W notatce podaj godzinę, miejsce, zachowanie, wykonane działania oraz to, kto może potwierdzić przebieg. Rozdziel własne obserwacje od relacji innych. Zapisz dokładny cytat tylko wtedy, gdy pamiętasz jego brzmienie."},{"heading":"Jak zastosować ją w praktyce","text":"Przekaż notatkę kanałem uzgodnionym przez organizację. Ogranicz dane do potrzebnych, zachowaj poufność i ustal, kto przejął odpowiedzialność za dalsze działanie. Jeżeli organizacja stosuje numer zgłoszenia, zapisz go. Osoby dotknięte zdarzeniem zapytaj o potrzebę przerwy, kontaktu z bliskimi lub dostępu do odpowiedniego wsparcia. Daj im wybór co do rozmowy i formy kontaktu."},{"heading":"Co ustalić na dyżurze","text":"Na omówieniu po zdarzeniu przyjrzyjcie się warunkom, które da się zmienić. Czy zespół znał kontakt awaryjny? Czy droga wyjścia była dostępna? Czy obsada odpowiadała ryzyku? Ustalcie zmianę, osobę odpowiedzialną i termin sprawdzenia. Powrót może oznaczać dyżur w parze, pracę w innym miejscu lub przerwę. Uzgodnij warunki przed wejściem ponownie w podobną sytuację."},{"heading":"Co zrobić krok po kroku","text":"1. Sprawdź, kto otrzymał pomoc i kto przejął sytuację.\n2. Zapisz czas, miejsce, fakty, źródła informacji i wykonane działania.\n3. Przekaż zgłoszenie odpowiednim kanałem i uzgodnij dalszy kontakt.\n4. Ustal poprawki w organizacji dyżuru oraz warunki powrotu."},{"heading":"Sytuacja z dyżuru","text":"Podczas rozdawania darów ktoś przewrócił krzesło przy wyjściu i na chwilę zastawił przejście. Dyżur przerwano. Następnego dnia masz w grafiku to samo stanowisko."},{"heading":"Przećwicz","text":"Napisz notatkę o fikcyjnym incydencie. Dodaj zmianę organizacyjną, osobę odpowiedzialną i termin sprawdzenia."},{"heading":"Sprawdź wynik po wykonaniu","text":"Zgłoś zdarzenie. Zapytaj, kto sprawdzi ustawienie stanowiska i będzie do pomocy. Jeśli uzgodnionych zabezpieczeń brakuje, poproś o inne zadanie albo odłóż powrót.\n\nKryterium ćwiczenia. Notatka zawiera miejsce, czas, zachowanie, działania i odbiorcę. Zmiana jest wykonalna i ma wskazaną osobę odpowiedzialną."}],"learning":{"intro":"Sporządzisz krótką notatkę i uzgodnisz warunki bezpiecznego powrotu.","situation":"Podczas rozdawania darów ktoś przewrócił krzesło przy wyjściu i na chwilę zastawił przejście. Dyżur przerwano. Następnego dnia masz w grafiku to samo stanowisko.","example":"Zgłoś zdarzenie. Zapytaj, kto sprawdzi ustawienie stanowiska i będzie do pomocy. Jeśli uzgodnionych zabezpieczeń brakuje, poproś o inne zadanie albo odłóż powrót.","task":"Napisz notatkę o fikcyjnym incydencie. Dodaj zmianę organizacyjną, osobę odpowiedzialną i termin sprawdzenia.","question":"Co wpiszesz do notatki, gdy sam nie widziałeś przewrócenia krzesła?","options":["Na pewno zrobił to uczestnik celowo.","Z informacji od osoby obsługującej wejście wynika, że krzesło przewrócono około 17.20.","Widziałem, jak uczestnik przewrócił krzesło."],"correct":1,"explanation":"Przypisanie relacji do jej źródła pozwala oddzielić ją od własnej obserwacji."},"references":[{"title":"Zgłaszanie i analiza incydentów przemocy – HSE","url":"https://www.hse.gov.uk/violence/employer/reporting-learning-from-incidents.htm"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Zgłaszanie naruszeń ochrony danych – Urząd Ochrony Danych Osobowych","url":"https://uodo.gov.pl/pl/525/2584"}]}},
{"lesson_no":24,"title_pl":"Ochrona dzieci przed krzywdzeniem","material":{"module":7,"sections":[{"heading":"Cel lekcji","text":"Sprawdzisz zasady pracy z dziećmi i przećwiczysz reakcję, gdy dziecko mówi o krzywdzeniu."},{"heading":"Najważniejsza zasada","text":"Przed rozpoczęciem poznaj standardy ochrony małoletnich organizacji, osobę przyjmującą zgłoszenia i jej zastępstwo. Ustal zasady spotkań indywidualnych, kontaktu poza zajęciami, transportu, zdjęć i odbioru dziecka. W Polsce obowiązek wprowadzenia standardów dotyczy podmiotów wskazanych w ustawie. Przy dopuszczaniu osób do działalności z dziećmi w zakresie określonym w art. 21 ustawa przewiduje obowiązki weryfikacji. Organizator powinien wyjaśnić, jakie zasady dotyczą Twojej roli."},{"heading":"Jak zastosować ją w praktyce","text":"Gdy dziecko opowie o krzywdzie, wysłuchaj je spokojnie. Podziękuj za powiedzenie. Wyjaśnij, że przekażesz sprawę osobie, która może pomóc. Zadaj wyłącznie pytania potrzebne do ustalenia bezpieczeństwa. Zrezygnuj z obietnic tajemnicy, pytań sugerujących odpowiedź i samodzielnego rozstrzygania, co się wydarzyło. Powstrzymaj się od konfrontacji z osobą wskazaną przez dziecko. Zapisz okoliczności, własne obserwacje i zapamiętane słowa dziecka."},{"heading":"Co ustalić na dyżurze","text":"Jeśli bezpieczeństwo dziecka jest bezpośrednio zagrożone, dzwoń pod 112. Niezwłocznie przekaż podejrzenie według standardów, a gdy dotyczy osoby odpowiedzialnej za ochronę, użyj drogi zapasowej. Art. 240 § 1 Kodeksu karnego nakłada obowiązek niezwłocznego zawiadomienia organu ścigania, gdy masz wiarygodną wiadomość o jednym z czynów wymienionych w tym przepisie. W takiej sytuacji zawiadom Policję lub prokuraturę bez czekania na wewnętrzną akceptację. Przed kontaktem z rodzicem lub opiekunem sprawdź procedurę, zwłaszcza jeśli ta osoba może być zamieszana w krzywdzenie."},{"heading":"Co zrobić krok po kroku","text":"1. Zapoznaj się ze standardami i nazwij kontakt podstawowy oraz zapasowy.\n2. Wysłuchaj i wyjaśnij dziecku, komu przekażesz informację.\n3. Przy bezpośrednim zagrożeniu wezwij pomoc i uruchom ścieżkę ochrony dziecka.\n4. Przekaż poufną notatkę. Jeśli zachodzi obowiązek z art. 240 § 1 k.k., niezwłocznie zawiadom Policję lub prokuraturę."},{"heading":"Sytuacja z dyżuru","text":"Po zajęciach dziecko mówi, że boi się wrócić do domu, bo wczoraj wujek je uderzył. Prosi o zachowanie tajemnicy. Nie wiesz, kto ma je odebrać."},{"heading":"Przećwicz","text":"Przygotuj dwie pierwsze wypowiedzi do dziecka i poufną notatkę na fikcyjnym przykładzie. Przećwicz to z dorosłą osobą."},{"heading":"Sprawdź wynik po wykonaniu","text":"„Dziękuję, że mi o tym mówisz. Teraz sprawdzę, jak zapewnić Ci bezpieczeństwo. Powiem o tym osobie, której zadaniem jest pomaganie dzieciom”. Pilnie skontaktuj się z osobą odpowiedzialną za ochronę dzieci, by ustalić postępowanie przed odbiorem. Przy bezpośrednim zagrożeniu dzwoń pod 112.\n\nKryterium ćwiczenia. Rozmowa obejmuje wysłuchanie i wyjaśnienie następnego kroku. Notatka oddaje słowa dziecka bez interpretacji i wskazuje właściwą ścieżkę zgłoszenia."}],"learning":{"intro":"Sprawdzisz zasady pracy z dziećmi i przećwiczysz reakcję, gdy dziecko mówi o krzywdzeniu.","situation":"Po zajęciach dziecko mówi, że boi się wrócić do domu, bo wczoraj wujek je uderzył. Prosi o zachowanie tajemnicy. Nie wiesz, kto ma je odebrać.","example":"„Dziękuję, że mi o tym mówisz. Teraz sprawdzę, jak zapewnić Ci bezpieczeństwo. Powiem o tym osobie, której zadaniem jest pomaganie dzieciom”. Pilnie skontaktuj się z osobą odpowiedzialną za ochronę dzieci, by ustalić postępowanie przed odbiorem. Przy bezpośrednim zagrożeniu dzwoń pod 112.","task":"Przygotuj dwie pierwsze wypowiedzi do dziecka i poufną notatkę na fikcyjnym przykładzie. Przećwicz to z dorosłą osobą.","question":"Jak odpowiedzieć, gdy dziecko prosi o tajemnicę?","options":["Obiecuję zachować tajemnicę, jeśli dziecko opowie całość.","Dziękuję za zaufanie i wyjaśniam, że przekażę sprawę osobie odpowiedzialnej za pomoc.","Zaczynam ustalać każdy szczegół, żeby samodzielnie ocenić wiarygodność."],"correct":1,"explanation":"Spokojne wysłuchanie i szybkie przekazanie informacji pozwalają rozpocząć pomoc."},"references":[{"title":"Ustawa o przeciwdziałaniu zagrożeniom przestępczością na tle seksualnym i ochronie małoletnich","url":"https://dziennikustaw.gov.pl/DU/2026/110"},{"title":"Vademecum. Wolontariat w szkole zgodnie z prawem – NIW","url":"https://niw.gov.pl/czytelnia/vademecum-wolontariat-w-szkole-zgodnie-z-prawem/"},{"title":"Standardy ochrony dzieci – Fundacja Dajemy Dzieciom Siłę","url":"https://standardy.fdds.pl/standardy"},{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"},{"title":"Kodeks karny – art. 240 § 1","url":"https://eli.gov.pl/eli/DU/2026/1342/ogl"}]}},
{"lesson_no":25,"title_pl":"Wsparcie dorosłych w sytuacji zależności","material":{"module":7,"sections":[{"heading":"Cel lekcji","text":"Zapytasz o zgodę i potrzeby osoby oraz rozpoznasz sytuację, którą trzeba przekazać dalej."},{"heading":"Najważniejsza zasada","text":"Zwracaj się bezpośrednio do osoby, której pomagasz. Zapytaj, czego potrzebuje i jak chce wykonać daną czynność. Na przykład przed przestawieniem wózka, dotknięciem rzeczy lub wejściem do mieszkania uzyskaj zgodę. Gdy komunikacja jest trudna, użyj dostępnej formy, daj czas na odpowiedź i zapytaj o pośrednika, któremu ta osoba ufa. Wiek, niepełnosprawność i obecność opiekuna same w sobie nie rozstrzygają, kto podejmuje decyzję."},{"heading":"Jak zastosować ją w praktyce","text":"Zwróć uwagę na konkretne sygnały, takie jak wymuszanie pieniędzy, groźby, uniemożliwianie rozmowy czy zabieranie potrzebnych środków. Jeśli rozmowa jest bezpieczna, zapytaj o pilne potrzeby i o to, czy osoba chce wsparcia w skontaktowaniu się ze specjalistyczną usługą. Ustal bezpieczny kanał i porę kontaktu. Sprawdź ścieżkę zgłoszenia organizacji i obowiązki właściwe dla sytuacji. Jeżeli trwa zagrożenie wymagające natychmiastowej pomocy, dzwoń pod 112."},{"heading":"Co ustalić na dyżurze","text":"Trzymaj się uzgodnionego zakresu pomocy. Możesz znaleźć zweryfikowaną informację, pomóc wykonać połączenie lub przekazać osobę pracownikowi odpowiedniej instytucji. Gdy ktoś prosi o hasło, kod PIN lub zarządzanie pieniędzmi poza zadaniem, zatrzymaj się i skonsultuj bezpieczną formę wsparcia. Zapisuj tylko informacje potrzebne do działania. Jeżeli kontakt z rodziną może narazić osobę na dalszą presję, omów dalsze kroki z uprawnionym zespołem."},{"heading":"Co zrobić krok po kroku","text":"1. Zapytaj bezpośrednio o preferencje, zgodę i sposób komunikacji.\n2. Rozpoznaj natychmiastowe zagrożenie i w razie potrzeby wezwij służby.\n3. Skorzystaj z procedury organizacji i uzgodnij bezpieczny kontakt.\n4. Przekaż potrzebne fakty, chroniąc prywatność i zakres decyzji osoby."},{"heading":"Sytuacja z dyżuru","text":"Podczas dostawy zakupów opiekun odpowiada za dorosłą osobę. Gdy wychodzi, osoba mówi, że ktoś zatrzymuje jej kartę bankową i że boi się dostać telefon wieczorem."},{"heading":"Przećwicz","text":"Ułóż po jednym pytaniu o zgodę na pomoc, pilną potrzebę i bezpieczny sposób dalszego kontaktu."},{"heading":"Sprawdź wynik po wykonaniu","text":"Zapytaj o pilne zagrożenie i bezpieczny sposób kontaktu. W sytuacji wymagającej natychmiastowej interwencji wezwij służby. W pozostałych przypadkach przekaż potrzebne fakty uprawnionym osobom i skonsultuj dalsze wsparcie. Uszanuj uzgodnioną porę kontaktu.\n\nKryterium ćwiczenia. Pytania kierujesz bezpośrednio do osoby wspieranej. Dajesz wybór formy wsparcia i znasz działanie przy bezpośrednim zagrożeniu."}],"learning":{"intro":"Zapytasz o zgodę i potrzeby osoby oraz rozpoznasz sytuację, którą trzeba przekazać dalej.","situation":"Podczas dostawy zakupów opiekun odpowiada za dorosłą osobę. Gdy wychodzi, osoba mówi, że ktoś zatrzymuje jej kartę bankową i że boi się dostać telefon wieczorem.","example":"Zapytaj o pilne zagrożenie i bezpieczny sposób kontaktu. W sytuacji wymagającej natychmiastowej interwencji wezwij służby. W pozostałych przypadkach przekaż potrzebne fakty uprawnionym osobom i skonsultuj dalsze wsparcie. Uszanuj uzgodnioną porę kontaktu.","task":"Ułóż po jednym pytaniu o zgodę na pomoc, pilną potrzebę i bezpieczny sposób dalszego kontaktu.","question":"Jak reagujesz na prośbę o przejęcie karty bankowej i kodu PIN podczas zwykłej wizyty?","options":["Wezmę kartę i zapiszę kod w notatniku.","Przekażę kod innemu wolontariuszowi, żeby podzielić odpowiedzialność.","Odmówię przejęcia karty i kodu. Uzgodnię bezpieczną formę pomocy."],"correct":2,"explanation":"Dostęp do karty i kodu wykracza poza zwykłe wsparcie i może narazić osobę na szkodę."},"references":[{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Psychological First Aid – centrum referencyjne IFRC","url":"https://pscentre.org/wp-content/uploads/2018/12/12007_psc_pfa_guide_T2_samlet_low.pdf"},{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"},{"title":"Zgłaszanie naruszeń ochrony danych – Urząd Ochrony Danych Osobowych","url":"https://uodo.gov.pl/pl/525/2584"}]}},
{"lesson_no":26,"title_pl":"Pierwsza pomoc psychologiczna","material":{"module":7,"sections":[{"heading":"Cel lekcji","text":"Zaproponujesz doraźne wsparcie po trudnym zdarzeniu i połączysz osobę z odpowiednią pomocą."},{"heading":"Najważniejsza zasada","text":"Pierwsza pomoc psychologiczna polega na zapewnieniu doraźnego wsparcia osobie, która doświadczyła trudnego zdarzenia. Zacznij od sprawdzenia, czy miejsce jest bezpieczne, czy potrzebna jest pomoc medyczna i czy osoba ma pilną potrzebę. Możesz zaproponować spokojniejsze miejsce, kontakt z bliskim lub sprawdzenie informacji. Przedstaw się, powiedz, z jakiej jesteś organizacji, i zapytaj, czy osoba chce skorzystać z pomocy."},{"heading":"Jak zastosować ją w praktyce","text":"Wysłuchaj tego, co osoba sama chce powiedzieć. Daj czas na odpowiedź i zaakceptuj, jeśli woli milczeć. Pomóż ustalić najbliższy krok pytaniem „Co teraz najbardziej by Pani pomogło?”. Pomoc polega na zmniejszeniu najpilniejszej trudności. Unikaj nacisku na opowiadanie szczegółów, diagnoz, ocen i zapewnień, że wszystko się ułoży. Gdy potrzebna jest specjalistyczna pomoc, ustal z osobą, jak ją uzyskać."},{"heading":"Co ustalić na dyżurze","text":"Połącz osobę z konkretną pomocą. Może to być członek zespołu, sprawdzona lokalna usługa albo bliski wybrany przez tę osobę. Uzgodnij, kto podejmie dalszy kontakt. W razie bezpośredniego zagrożenia zdrowia lub życia wezwij służby zgodnie z sytuacją i poinformuj organizację. Po zdarzeniu zadbaj również o własną przerwę i poproś o wsparcie, jeśli go potrzebujesz."},{"heading":"Co zrobić krok po kroku","text":"1. Sprawdź bezpieczeństwo i pilne potrzeby.\n2. Przedstaw się, zaproponuj pomoc i daj osobie wybór.\n3. Wysłuchaj na jej warunkach i ustal jeden wykonalny następny krok.\n4. Połącz osobę z pomocą i potwierdź, kto przejmuje sprawę."},{"heading":"Sytuacja z dyżuru","text":"Po ewakuacji roztrzęsiona osoba stoi z boku i mówi, że nie wie, gdzie jest jej telefon. Miejsce zbiórki jest bezpieczne."},{"heading":"Przećwicz","text":"Odegraj dwuminutową rozmowę po ewakuacji. Druga osoba może odmówić rozmowy lub wybrać jedną z dwóch form wsparcia."},{"heading":"Sprawdź wynik po wykonaniu","text":"Przedstaw się. Zapytaj, czy chce, żeby ktoś z nią chwilę został i pomógł skontaktować się z wybraną osobą. Jeśli wyrazi zgodę, pomóż ustalić kontakt. W razie zagrożenia zdrowia powiadom służby.\n\nKryterium ćwiczenia. Sprawdzasz bezpieczeństwo, pytasz o zgodę, respektujesz odmowę i potrafisz uzgodnić konkretne działanie."}],"learning":{"intro":"Zaproponujesz doraźne wsparcie po trudnym zdarzeniu i połączysz osobę z odpowiednią pomocą.","situation":"Po ewakuacji roztrzęsiona osoba stoi z boku i mówi, że nie wie, gdzie jest jej telefon. Miejsce zbiórki jest bezpieczne.","example":"Przedstaw się. Zapytaj, czy chce, żeby ktoś z nią chwilę został i pomógł skontaktować się z wybraną osobą. Jeśli wyrazi zgodę, pomóż ustalić kontakt. W razie zagrożenia zdrowia powiadom służby.","task":"Odegraj dwuminutową rozmowę po ewakuacji. Druga osoba może odmówić rozmowy lub wybrać jedną z dwóch form wsparcia.","question":"Co pomoże osobie roztrzęsionej po zdarzeniu, która nie chce o nim opowiadać?","options":["Przekonam ją, by odtworzyła zdarzenie od początku.","Za jej zgodą sprawdzę bieżące potrzeby i pomogę skontaktować się z wybraną osobą lub usługą.","Zapewnię, że jutro na pewno poczuje się lepiej."],"correct":1,"explanation":"Pomoc jest dobrowolna i skupia się na aktualnych potrzebach."},"references":[{"title":"Psychologiczna pierwsza pomoc – WHO i Ministerstwo Zdrowia","url":"https://www.gov.pl/web/zdrowie/psychologiczna-pierwsza-pomoc-przewodnik-dla-pracownikow-w-terenie"},{"title":"Psychological First Aid – centrum referencyjne IFRC","url":"https://pscentre.org/wp-content/uploads/2018/12/12007_psc_pfa_guide_T2_samlet_low.pdf"},{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"}]}},
{"lesson_no":27,"title_pl":"Nagłe zdarzenie i rola wolontariusza","material":{"module":7,"sections":[{"heading":"Cel lekcji","text":"Połączysz ocenę bezpieczeństwa, wezwanie pomocy i jasny podział zadań do czasu przyjazdu służb."},{"heading":"Najważniejsza zasada","text":"Najpierw sprawdź, czy możesz bezpiecznie podejść. Ruch samochodów, dym, instalacja elektryczna, agresja lub nieznana substancja mogą stanowić zagrożenie także dla osoby udzielającej pomocy. Jeżeli miejsce jest niebezpieczne, zostań poza strefą zagrożenia i wezwij odpowiednią pomoc. W nagłym zagrożeniu zdrowia lub życia zadzwoń pod 112. Podaj lokalizację i to, co możesz zaobserwować."},{"heading":"Jak zastosować ją w praktyce","text":"Jeżeli podejście jest bezpieczne, stosuj się do instrukcji operatora i przekaż mu informacje o reakcji oraz oddychaniu osoby, o ile możesz to sprawdzić zgodnie z jego wskazówkami. Gdy są świadkowie, zwróć się do konkretnej osoby. Możesz poprosić o przyniesienie AED, jeśli jest dostępne, albo o wskazanie drogi ratownikom. Utrzymuj przejście i daj osobie poszkodowanej przestrzeń. Unikaj podawania jej leków lub napojów na własną rękę."},{"heading":"Co ustalić na dyżurze","text":"Przekaż służbom, co zauważyłeś, kiedy to nastąpiło i jakie czynności wykonano. Następnie postępuj według poleceń. Zgłoś zdarzenie w organizacji z poszanowaniem prywatności. Na wdrożeniu ustal, gdzie są apteczka, AED i droga dojazdu służb. Praktyczny kurs pierwszej pomocy pozwala przećwiczyć czynności ratunkowe na sprzęcie treningowym i pod okiem instruktora."},{"heading":"Co zrobić krok po kroku","text":"1. Sprawdź zagrożenia miejsca i wezwij pomoc, gdy jest potrzebna.\n2. Odpowiadaj na pytania operatora i wykonuj jego instrukcje.\n3. Przydziel świadkom konkretne, bezpieczne zadania.\n4. Przekaż ratownikom obserwacje i działania, a następnie zgłoś zdarzenie organizacji."},{"heading":"Sytuacja z dyżuru","text":"Na wydarzeniu osoba osuwa się na podłogę i nie odpowiada na wołanie. W holu jest AED, a do budynku prowadzą dwa wejścia."},{"heading":"Przećwicz","text":"Przećwicz podział zadań podczas fikcyjnego zdarzenia. Poproś uczestników o powtórzenie poleceń. Pomiń wykonywanie prawdziwego połączenia alarmowego."},{"heading":"Sprawdź wynik po wykonaniu","text":"Sprawdź bezpieczeństwo miejsca i zadzwoń pod 112 lub poleć to konkretnej osobie. Poproś inną o AED i kolejną o wskazanie wejścia. Postępuj zgodnie z instrukcjami operatora i przekaż ratownikom obserwacje.\n\nKryterium ćwiczenia. Oceniasz bezpieczeństwo, wskazujesz osobę wzywającą pomoc i przekazujesz co najmniej dwa bezpieczne zadania."}],"learning":{"intro":"Połączysz ocenę bezpieczeństwa, wezwanie pomocy i jasny podział zadań do czasu przyjazdu służb.","situation":"Na wydarzeniu osoba osuwa się na podłogę i nie odpowiada na wołanie. W holu jest AED, a do budynku prowadzą dwa wejścia.","example":"Sprawdź bezpieczeństwo miejsca i zadzwoń pod 112 lub poleć to konkretnej osobie. Poproś inną o AED i kolejną o wskazanie wejścia. Postępuj zgodnie z instrukcjami operatora i przekaż ratownikom obserwacje.","task":"Przećwicz podział zadań podczas fikcyjnego zdarzenia. Poproś uczestników o powtórzenie poleceń. Pomiń wykonywanie prawdziwego połączenia alarmowego.","question":"Co zrobisz, gdy widzisz poszkodowaną osobę w miejscu, do którego nie da się bezpiecznie wejść?","options":["Podejdę szybko, jeśli ktoś będzie mnie obserwował.","Zostanę w bezpiecznym miejscu, zadzwonię pod 112 i opiszę zagrożenie.","Poproszę przypadkowego świadka, aby podszedł pierwszy."],"correct":1,"explanation":"Wezwiesz służby, zachowując bezpieczeństwo własne i osób w pobliżu."},"references":[{"title":"Pierwsza pomoc – Poradnik bezpieczeństwa, Gov.pl","url":"https://www.gov.pl/web/poradnikbezpieczenstwa/pierwsza-pomoc"},{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"}]}},
{"lesson_no":28,"title_pl":"Żywność i pomoc rzeczowa","material":{"module":8,"sections":[{"heading":"Cel lekcji","text":"Przyjąć, posegregować i przekazać dary według potrzeb i zasad punktu."},{"heading":"Najważniejsza zasada","text":"Zbiórka zaczyna się od listy potrzeb przygotowanej z organizacją i aktualizowanej w trakcie działania. Ustal, czego punkt potrzebuje, czego nie przyjmuje, kto odbiera transport i co dzieje się z nadwyżkami. Przy wydawaniu mów, co jest dostępne, kiedy można sprawdzić kolejną dostawę i gdzie złożyć prośbę o zamianę."},{"heading":"Jak zastosować ją w praktyce","text":"W punkcie żywnościowym pracuj według instrukcji higieny, sortowania, przechowywania i transportu. Oddziel uszkodzone opakowania oraz produkty, których składu lub warunków przechowania nie potrafisz potwierdzić. O dalszym postępowaniu decyduje osoba odpowiedzialna za punkt. Gdy ktoś pyta o alergeny, wskaż potwierdzoną informację lub uczciwie powiedz, że organizacja jeszcze jej nie ma."},{"heading":"Co ustalić na dyżurze","text":"Sprawdzaj potrzeby dyskretnie. Zapytaj, czy osoba może skorzystać z produktów i czy potrzebuje dostępnej zamiany. W rejestrze podawaj ilości i uzgodnione identyfikatory. Dane odbiorców zapisuj tylko w wyznaczonym systemie. Zamykając zmianę, przekaż braki i nadwyżki oraz sposób postępowania z odłożonymi produktami."},{"heading":"Co zrobić krok po kroku","text":"1. Sprawdź aktualną listę potrzeb i zasady przyjęcia.\n2. Oznacz wyjątki i skieruj je do osoby odpowiedzialnej.\n3. Wydawaj według uzgodnionych kryteriów, zachowując dyskrecję.\n4. Zapisz ilości i przekaż następnej zmianie informacje o brakach."},{"heading":"Sytuacja z dyżuru","text":"Darczyńca przywozi domowe potrawy bez etykiet i prosi o ich natychmiastowe wydanie. W kolejce ktoś pyta o alergeny."},{"heading":"Przećwicz","text":"Ułóż krótką instrukcję na wypadek nadwyżki odzieży, braku informacji o alergenach i otwartego opakowania."},{"heading":"Sprawdź wynik po wykonaniu","text":"Wyjaśnij zasady punktu. „Sprawdzę, czy możemy przyjąć tę żywność. Do tego czasu jej nie wydamy”. Odłóż dostawę zgodnie z procedurą i przekaż sprawę odpowiedzialnej osobie. Odbiorcy wskaż oznaczone produkty.\n\nKryterium ćwiczenia. Instrukcja wskazuje, co oddzielić, kogo zawiadomić i jak wyjaśnić decyzję."}],"learning":{"intro":"Przyjąć, posegregować i przekazać dary według potrzeb i zasad punktu.","situation":"Darczyńca przywozi domowe potrawy bez etykiet i prosi o ich natychmiastowe wydanie. W kolejce ktoś pyta o alergeny.","example":"Wyjaśnij zasady punktu. „Sprawdzę, czy możemy przyjąć tę żywność. Do tego czasu jej nie wydamy”. Odłóż dostawę zgodnie z procedurą i przekaż sprawę odpowiedzialnej osobie. Odbiorcy wskaż oznaczone produkty.","task":"Ułóż krótką instrukcję na wypadek nadwyżki odzieży, braku informacji o alergenach i otwartego opakowania.","question":"Nie możesz potwierdzić warunków przechowywania żywności. Co robisz?","options":["Wydaję ją jak najszybciej","Oddzielam dostawę i proszę odpowiedzialną osobę o decyzję","Przekazuję ją bez oznaczenia"],"correct":1,"explanation":"Warunki wymagają oceny według instrukcji punktu przed wydaniem."},"references":[{"title":"Zbiórki Żywności – Federacja Polskich Banków Żywności","url":"https://bankizywnosci.pl/projekty/zbiorki-zywnosci/"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"}]}},
{"lesson_no":29,"title_pl":"Wydarzenia, kultura i sport","material":{"module":8,"sections":[{"heading":"Cel lekcji","text":"Przeprowadzić bezpieczny dyżur przy wejściu, informacji lub obsłudze uczestników."},{"heading":"Najważniejsza zasada","text":"Na wydarzeniu role działają równolegle. Sprawdzasz bilety albo wskazujesz drogę, a organizator, ochrona i ratownicy wykonują ustalone obowiązki. Podczas odprawy znajdź główne i dostępne wejście, toalety, drogę ewakuacji i punkt pomocy. Zapytaj, jak wezwać wsparcie w hałasie i jakie informacje podawać przez radio."},{"heading":"Jak zastosować ją w praktyce","text":"Zostaw przejścia drożne. Gdy tworzy się tłok, poinformuj osobę nadzorującą, gdzie zagęszcza się tłum i jakie przejście jest utrudnione. Komunikaty dla uczestników przekazuj zgodnie z odprawą. W bezpośrednim zagrożeniu działaj według procedury alarmowej i wzywaj służby, gdy potrzebna jest natychmiastowa interwencja."},{"heading":"Co ustalić na dyżurze","text":"Przed dyżurem zapytaj o procedurę dla zagubionego dziecka, rzeczy znalezionych oraz osób proszących o dostępny sposób wejścia. Dziecko kieruj do ustalonej procedury wraz z personelem. W publicznych komunikatach ogranicz zakres danych do informacji dopuszczonych przez organizację. Po dyżurze potwierdź przejęcie nierozwiązanych spraw."},{"heading":"Co zrobić krok po kroku","text":"1. Odbierz mapę i uzgodnij zadanie.\n2. Sprawdź dostępne trasy i punkty pomocy.\n3. Zgłaszaj miejsce, problem i pilność.\n4. Oddaj sprzęt i potwierdź przekazanie spraw."},{"heading":"Sytuacja z dyżuru","text":"Kolejka przy wejściu bocznym blokuje przejście, a uczestnicy zaczynają się przepychać."},{"heading":"Przećwicz","text":"Rozrysuj szkic wydarzenia z pięcioma punktami i przygotuj piętnastosekundowy meldunek o tłoku."},{"heading":"Sprawdź wynik po wykonaniu","text":"Użyj uzgodnionego kanału. „Wejście boczne. Kolejka blokuje drzwi, zaczyna się przepychanie. Potrzebuję osoby prowadzącej ruch”. Zachowaj dla siebie bezpieczne miejsce i stosuj wskazania organizatora.\n\nKryterium ćwiczenia. W meldunku są miejsce, problem i żądane wsparcie. Na szkicu są trasa dostępna i punkt pomocy."}],"learning":{"intro":"Przeprowadzić bezpieczny dyżur przy wejściu, informacji lub obsłudze uczestników.","situation":"Kolejka przy wejściu bocznym blokuje przejście, a uczestnicy zaczynają się przepychać.","example":"Użyj uzgodnionego kanału. „Wejście boczne. Kolejka blokuje drzwi, zaczyna się przepychanie. Potrzebuję osoby prowadzącej ruch”. Zachowaj dla siebie bezpieczne miejsce i stosuj wskazania organizatora.","task":"Rozrysuj szkic wydarzenia z pięcioma punktami i przygotuj piętnastosekundowy meldunek o tłoku.","question":"Jak pomagasz osobie, która zgłasza zagubienie dziecka?","options":["Publikuję pełne dane w grupie wolontariuszy","Odsyłam ją do dowolnego wolontariusza bez meldunku","Uruchamiam ustaloną procedurę i kontaktuję się z odpowiedzialną osobą"],"correct":2,"explanation":"Przygotowana procedura przyspiesza reakcję i ogranicza rozpowszechnianie danych."},"references":[{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"},{"title":"Vademecum. Wolontariat w szkole zgodnie z prawem – NIW","url":"https://niw.gov.pl/czytelnia/vademecum-wolontariat-w-szkole-zgodnie-z-prawem/"}]}},
{"lesson_no":30,"title_pl":"Seniorzy, szpitale i hospicja","material":{"module":8,"sections":[{"heading":"Cel lekcji","text":"Oferować towarzyszenie w granicach roli, zgody i zasad placówki."},{"heading":"Najważniejsza zasada","text":"Towarzyszenie może oznaczać rozmowę, wspólne czytanie, pomoc w zajęciach grupowych lub organizację akcji na rzecz placówki. Ustal, które zadania wykonujesz po wdrożeniu, które w obecności personelu i jak skontaktować się z opiekunem zmiany. Poznaj zasady prywatności, higieny, wejścia i kontaktu z rodziną."},{"heading":"Jak zastosować ją w praktyce","text":"Zapytaj, czy osoba chce rozmowy i jakiej pomocy potrzebuje. Uszanuj ciszę lub odmowę. Jeśli ktoś pyta o leczenie, dietę, transport medyczny, dawkowanie leków lub przemieszczenie z łóżka, skieruj sprawę do personelu. Gdy stan osoby budzi pilny niepokój, wezwij pomoc zgodnie z procedurą placówki bez opóźniania interwencji."},{"heading":"Co ustalić na dyżurze","text":"Po trudnym dyżurze porozmawiaj z opiekunem o swoich potrzebach i warunkach wsparcia. Informacje o pacjencie pozostają w uprawnionym zespole. Jeśli ktoś prosi o Twój numer, pieniądze lub pomoc poza placówką, przedstaw sposób kontaktu przewidziany przez organizację i zapytaj opiekuna o dostępne rozwiązanie."},{"heading":"Co zrobić krok po kroku","text":"1. Potwierdź zasady i osobę do kontaktu.\n2. Zapytaj o zgodę na towarzyszenie.\n3. Prośby medyczne kieruj do personelu.\n4. Przekaż obserwacje uprawnionej osobie."},{"heading":"Sytuacja z dyżuru","text":"Osoba, której towarzyszysz, prosi o zmianę dawki leku i mówi, że rodzina zwykle jej w tym pomaga."},{"heading":"Przećwicz","text":"Napisz odpowiedzi na prośby o towarzyszenie, podanie leku i prywatny numer telefonu."},{"heading":"Sprawdź wynik po wykonaniu","text":"Powiedz, że zawołasz personel, który może pomóc. Przekaż prośbę dokładnie i przy widocznym pogorszeniu stanu zawiadom personel pilnie.\n\nKryterium ćwiczenia. Każda odpowiedź jest życzliwa i określa dostępny następny krok."}],"learning":{"intro":"Oferować towarzyszenie w granicach roli, zgody i zasad placówki.","situation":"Osoba, której towarzyszysz, prosi o zmianę dawki leku i mówi, że rodzina zwykle jej w tym pomaga.","example":"Powiedz, że zawołasz personel, który może pomóc. Przekaż prośbę dokładnie i przy widocznym pogorszeniu stanu zawiadom personel pilnie.","task":"Napisz odpowiedzi na prośby o towarzyszenie, podanie leku i prywatny numer telefonu.","question":"Kto może zdecydować o zmianie dawki?","options":["Osoba z odpowiednimi uprawnieniami","Wolontariusz po przeczytaniu ulotki","Inny wolontariusz na zmianie"],"correct":0,"explanation":"Zadanie wolontariusza polega na przekazaniu prośby właściwemu personelowi."},"references":[{"title":"Centrum Wolontariatu Fundacji Hospicyjnej","url":"https://fundacjahospicyjna.pl/centrum-wolontariatu-fundacji-hospicyjnej/"},{"title":"Pierwsza pomoc – Poradnik bezpieczeństwa, Gov.pl","url":"https://www.gov.pl/web/poradnikbezpieczenstwa/pierwsza-pomoc"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"}]}},
{"lesson_no":31,"title_pl":"Zwierzęta i środowisko","material":{"module":8,"sections":[{"heading":"Cel lekcji","text":"Przygotować się do zadania w schronisku lub w terenie i przerwać je przy nieznanym ryzyku."},{"heading":"Najważniejsza zasada","text":"W schronisku można pomagać w porządkach, logistyce, przygotowaniu materiałów adopcyjnych i zadaniach opiekuńczych. Placówka ustala, kto ma dostęp do danego sektora oraz komu przydzielić konkretne zwierzę. Sprawdź oznaczenia i sposób zgłaszania ucieczki, urazu lub nietypowego zachowania. Zgłaszaj przyjęcie i zakończenie zadania."},{"heading":"Jak zastosować ją w praktyce","text":"W akcji środowiskowej sprawdź obszar, pogodę, sprzęt, limity pracy oraz sposób zbiórki odpadów. Przy ostrym, chemicznym lub nieznanym odpadzie przerwij pracę i zgłoś lokalizację z bezpiecznej odległości. Zostaw obsługę odpowiednio przygotowanym osobom. Ustal, kiedy zespół przerywa pracę ze względu na pogodę lub warunki terenowe."},{"heading":"Co ustalić na dyżurze","text":"Wkład może polegać także na prowadzeniu list, przygotowaniu grafik czy sortowaniu wyposażenia. Jeśli przydział wykracza poza Twoje doświadczenie, poproś o inne zadanie i ustal możliwość szkolenia. Po zmianie zgłoś, co zostało wykonane, co zostało w terenie i jakie miejsce wymaga zabezpieczenia."},{"heading":"Co zrobić krok po kroku","text":"1. Ustal czynności, sprzęt i warunki przerwania.\n2. Potwierdź osobę nadzorującą i łączność.\n3. Przy zmianie ryzyka przerwij zadanie i zgłoś je.\n4. Po pracy przekaż lokalizację pozostałych spraw."},{"heading":"Sytuacja z dyżuru","text":"Przy sprzątaniu znajdujesz nieoznaczony pojemnik z wyciekiem. Druga osoba chce go przenieść na skraj ścieżki."},{"heading":"Przećwicz","text":"Przygotuj dwie krótkie odprawy. Jedną dla schroniska, drugą dla akcji terenowej."},{"heading":"Sprawdź wynik po wykonaniu","text":"Odejdźcie na bezpieczną odległość. Podajcie koordynatorowi lokalizację i opis. Jeśli wyciek wymaga natychmiastowej interwencji służb, wezwijcie 112 z bezpiecznego miejsca.\n\nKryterium ćwiczenia. Każda obejmuje zakres zadania, sprzęt, łączność i warunek przerwania."}],"learning":{"intro":"Przygotować się do zadania w schronisku lub w terenie i przerwać je przy nieznanym ryzyku.","situation":"Przy sprzątaniu znajdujesz nieoznaczony pojemnik z wyciekiem. Druga osoba chce go przenieść na skraj ścieżki.","example":"Odejdźcie na bezpieczną odległość. Podajcie koordynatorowi lokalizację i opis. Jeśli wyciek wymaga natychmiastowej interwencji służb, wezwijcie 112 z bezpiecznego miejsca.","task":"Przygotuj dwie krótkie odprawy. Jedną dla schroniska, drugą dla akcji terenowej.","question":"Kto przydziela konkretnego psa do wyprowadzenia?","options":["Pierwszy uczestnik spaceru","Upoważniona osoba w schronisku","Wybieram samodzielnie według wielkości psa"],"correct":1,"explanation":"Placówka zna sytuację zwierzęcia i wymagania danego zadania."},"references":[{"title":"Nabór do wolontariatu – Schronisko na Paluchu","url":"https://napaluchu.waw.pl/jak-pomoc/wolontariat/nabor-do-wolontariatu/"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"}]}},
{"lesson_no":32,"title_pl":"Mentoring, edukacja i integracja","material":{"module":9,"sections":[{"heading":"Cel lekcji","text":"Zaplanować wsparcie, które rozwija samodzielność uczestnika."},{"heading":"Najważniejsza zasada","text":"Mentoring może obejmować ćwiczenie języka, orientację w dzielnicy lub pomoc w korzystaniu z instytucji. Ustal z uczestnikiem jeden cel, który ma dla niego znaczenie. Pokaż przykład, wykonajcie kolejny razem i daj czas na samodzielną próbę. Na koniec zapytaj, co uczestnik zrobi następnym razem."},{"heading":"Jak zastosować ją w praktyce","text":"Przy zadaniach z dziećmi poznaj wymagania weryfikacji i zasady ochrony małoletnich przed rozpoczęciem. Używaj zatwierdzonych kanałów, godzin i miejsc spotkań. W pomocy językowej pytaj, jakiego języka i sposobu komunikacji potrzebuje dana osoba. W sprawie prawnej, urzędowej lub medycznej skieruj ją do właściwego specjalisty lub tłumacza, jeśli sytuacja tego wymaga."},{"heading":"Co ustalić na dyżurze","text":"Zapytaj, jaką część sprawy uczestnik chce załatwić z Twoją pomocą, a co woli zrobić samodzielnie. Pokaż, jak znaleźć potwierdzoną informację. Hasła i kody dostępu zostają pod kontrolą uczestnika. Przekaż organizacji wyłącznie informacje potrzebne do ustalonego celu."},{"heading":"Co zrobić krok po kroku","text":"1. Ustal cel i dozwolony kanał kontaktu.\n2. Pokaż przykład i zróbcie wspólną próbę.\n3. Skieruj pytania specjalistyczne do właściwej osoby.\n4. Sprawdź, co uczestnik wykonuje samodzielnie."},{"heading":"Sytuacja z dyżuru","text":"Uczestnik prosi Cię o zalogowanie się na jego konto i wysłanie pisma, które ma skutki prawne."},{"heading":"Przećwicz","text":"Zaplanuj dwudziestominutowe spotkanie dla osoby, która chce samodzielnie sprawdzać godziny lokalnych instytucji."},{"heading":"Sprawdź wynik po wykonaniu","text":"Wskaż oficjalną instrukcję i pomóż znaleźć właściwy punkt wsparcia. Uczestnik zachowuje kontrolę nad kontem. Ustal, kto może objaśnić znaczenie pisma.\n\nKryterium ćwiczenia. Plan zawiera jeden cel, ćwiczenie uczestnika i prostą metodę sprawdzenia wyniku."}],"learning":{"intro":"Zaplanować wsparcie, które rozwija samodzielność uczestnika.","situation":"Uczestnik prosi Cię o zalogowanie się na jego konto i wysłanie pisma, które ma skutki prawne.","example":"Wskaż oficjalną instrukcję i pomóż znaleźć właściwy punkt wsparcia. Uczestnik zachowuje kontrolę nad kontem. Ustal, kto może objaśnić znaczenie pisma.","task":"Zaplanuj dwudziestominutowe spotkanie dla osoby, która chce samodzielnie sprawdzać godziny lokalnych instytucji.","question":"Uczeń prosi o prywatne rozmowy poza systemem programu. Co robisz?","options":["Zgadzam się na tydzień","Ignoruję prośbę","Podaję dostępne kanały i zgłaszam trudność opiekunowi programu"],"correct":2,"explanation":"Zatwierdzone kanały chronią obie strony i ułatwiają ciągłość wsparcia."},"references":[{"title":"Standardy ochrony dzieci – Fundacja Dajemy Dzieciom Siłę","url":"https://standardy.fdds.pl/standardy"},{"title":"Vademecum. Wolontariat w szkole zgodnie z prawem – NIW","url":"https://niw.gov.pl/czytelnia/vademecum-wolontariat-w-szkole-zgodnie-z-prawem/"},{"title":"Psychologiczna pierwsza pomoc – WHO i Ministerstwo Zdrowia","url":"https://www.gov.pl/web/zdrowie/psychologiczna-pierwsza-pomoc-przewodnik-dla-pracownikow-w-terenie"}]}},
{"lesson_no":33,"title_pl":"Pomoc zdalna, kompetencyjna i pracownicza","material":{"module":9,"sections":[{"heading":"Cel lekcji","text":"Uzgodnić zdalne lub specjalistyczne zadanie wraz z zakresem, dostępami i przekazaniem."},{"heading":"Najważniejsza zasada","text":"Zdalnie możesz przygotować dostępne materiały, poprawić napisy do filmu, przetłumaczyć tekst lub uporządkować stronę. W wolontariacie kompetencyjnym dobierz zadanie do swoich kwalifikacji. W przypadku zespołu pracowników zadanie wynika z potrzeb organizacji, a udział pozostaje dobrowolny. Uzgodnij rezultat, odbiorcę, termin i kryteria przyjęcia pracy."},{"heading":"Jak zastosować ją w praktyce","text":"Pracuj na zatwierdzonych kontach i danych potrzebnych do zadania. Do prób poproś o fikcyjne dane. Prywatna poczta, chmura i narzędzie AI wymagają autoryzacji organizacji przed użyciem z jej danymi. Ustal też zasady udostępniania, autorstwa i zmian materiału, zwłaszcza gdy korzystasz z cudzych treści lub sprzętu pracodawcy."},{"heading":"Co ustalić na dyżurze","text":"Przed wykonaniem całości pokaż próbkę. Podczas przekazania przeprowadź krótką demonstrację, dodaj instrukcję i podaj miejsce zgłaszania usterek. Osoba przejmująca potwierdza, że może otworzyć i aktualizować materiał. Po zakończeniu zgłoś odebranie zbędnych dostępów."},{"heading":"Co zrobić krok po kroku","text":"1. Zapisz rezultat, kryteria i właściciela zadania.\n2. Ustal dozwolone dane, konta i narzędzia.\n3. Dostarcz próbkę do sprawdzenia.\n4. Przekaż wynik i instrukcję, a potem zamknij dostępy."},{"heading":"Sytuacja z dyżuru","text":"Kolega proponuje, by całe zestawienie danych uczestników przesłać do prywatnego narzędzia AI i tam je uporządkować."},{"heading":"Przećwicz","text":"Napisz kartę przekazania dla osoby, która przejmie aktualizację strony organizacji."},{"heading":"Sprawdź wynik po wykonaniu","text":"Zaproponuj zatwierdzone środowisko oraz test na fikcyjnych danych. Zanim otrzymasz dostęp, potwierdź dozwolone narzędzia i potrzebny zakres danych.\n\nKryterium ćwiczenia. Karta obejmuje akceptację, odpowiedzialność za aktualizację i termin odebrania dostępu."}],"learning":{"intro":"Uzgodnić zdalne lub specjalistyczne zadanie wraz z zakresem, dostępami i przekazaniem.","situation":"Kolega proponuje, by całe zestawienie danych uczestników przesłać do prywatnego narzędzia AI i tam je uporządkować.","example":"Zaproponuj zatwierdzone środowisko oraz test na fikcyjnych danych. Zanim otrzymasz dostęp, potwierdź dozwolone narzędzia i potrzebny zakres danych.","task":"Napisz kartę przekazania dla osoby, która przejmie aktualizację strony organizacji.","question":"Co ustalasz przed zdalną analizą danych?","options":["Zakres, kryteria, zatwierdzone dane i narzędzia","Wyłącznie termin","Wyłącznie dostęp administracyjny"],"correct":0,"explanation":"Te ustalenia pozwalają dostarczyć potrzebny efekt i ograniczyć dostęp do danych."},"references":[{"title":"United Nations Volunteers – ścieżki wolontariatu","url":"https://www.unv.org/become-volunteer/"},{"title":"Zgłaszanie naruszeń ochrony danych – Urząd Ochrony Danych Osobowych","url":"https://uodo.gov.pl/pl/525/2584"},{"title":"Praktyczny poradnik współpracy z wolontariuszami – Fundacja Stocznia","url":"https://stocznia.org.pl/publikacje/praktyczny-poradnik-wspolpracy-z-wolontariuszami/"}]}},
{"lesson_no":34,"title_pl":"Klęski żywiołowe i pomoc humanitarna","material":{"module":9,"sections":[{"heading":"Cel lekcji","text":"Dołączyć do skoordynowanej pomocy według aktualnych potrzeb i poleceń służb."},{"heading":"Najważniejsza zasada","text":"Podczas powodzi, pożaru czy ewakuacji potrzeby zmieniają się szybko. Zacznij od aktualnego komunikatu gminy, służb lub organizacji prowadzącej wsparcie. Sprawdź czas publikacji, obszar, potrzebne zasoby i punkt przyjmowania pomocy. Zaoferuj konkretną dostępność. Jedź dopiero po potwierdzeniu zadania i warunków."},{"heading":"Jak zastosować ją w praktyce","text":"Wolontariusze mogą pomagać w ewidencji dostaw, magazynie, informacji, tłumaczeniu lub przygotowaniu posiłków według procedury. Prace przy zagrożonych budynkach, zasilaniu, wodzie lub ewakuacji wymagają przygotowania i działania zgodnie z poleceniami służb. Gdy pojawia się nowe ryzyko, przejdź do ustalonego miejsca, potwierdź obecność i skontaktuj się z osobą prowadzącą."},{"heading":"Co ustalić na dyżurze","text":"Podawaj zweryfikowane, datowane komunikaty i prostuj nieaktualne informacje tym samym kanałem. Listy osób potrzebujących pomocy pozostają w uprawnionym obiegu. Szanuj kryteria dystrybucji, rób przerwy i przekaż zmianę, zanim przemęczenie zacznie wpływać na decyzje."},{"heading":"Co zrobić krok po kroku","text":"1. Zweryfikuj źródło, datę i adres.\n2. Potwierdź przydział, łączność i koniec zmiany.\n3. Przerwij przy nowym ryzyku i zgłoś się do osoby prowadzącej.\n4. Przekaż stan dostaw oraz otwarte sprawy."},{"heading":"Sytuacja z dyżuru","text":"Krąży wczorajszy apel o odzież i wyjazd do zalanej miejscowości. Dziś gmina prosi wyłącznie o wsparcie magazynu poza strefą zagrożenia."},{"heading":"Przećwicz","text":"Porównaj dwa fikcyjne apele. Sprawdź organizatora, czas, miejsce, potrzeby i sposób potwierdzenia przydziału."},{"heading":"Sprawdź wynik po wykonaniu","text":"Zgłoś gotowość do aktualnego zadania i zaczekaj na potwierdzenie. Skoryguj stary apel tam, gdzie wcześniej go udostępniłeś.\n\nKryterium ćwiczenia. Decyzja wskazuje aktualne źródło i konkretne bezpieczne zadanie."}],"learning":{"intro":"Dołączyć do skoordynowanej pomocy według aktualnych potrzeb i poleceń służb.","situation":"Krąży wczorajszy apel o odzież i wyjazd do zalanej miejscowości. Dziś gmina prosi wyłącznie o wsparcie magazynu poza strefą zagrożenia.","example":"Zgłoś gotowość do aktualnego zadania i zaczekaj na potwierdzenie. Skoryguj stary apel tam, gdzie wcześniej go udostępniłeś.","task":"Porównaj dwa fikcyjne apele. Sprawdź organizatora, czas, miejsce, potrzeby i sposób potwierdzenia przydziału.","question":"Co robisz przed wyjazdem do obszaru objętego klęską?","options":["Jadę z dostępnymi darami","Potwierdzam przydział i warunki u aktualnego organizatora","Kieruję się najpopularniejszym postem"],"correct":1,"explanation":"Przydział pozwala pomóc bez utrudniania działań służb i obciążania zaplecza."},"references":[{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"},{"title":"Pomoc dla powodzian – Dolnośląski Urząd Wojewódzki","url":"https://www.gov.pl/web/dolnoslaski-uw/pomoc-dla-powodzian2"}]}},
{"lesson_no":35,"title_pl":"Wolontariat zagraniczny i programy europejskie","material":{"module":9,"sections":[{"heading":"Cel lekcji","text":"Porównać oferty wyjazdowe według roli, wsparcia, kosztów i ryzyka."},{"heading":"Najważniejsza zasada","text":"Rozważ Europejski Korpus Solidarności, workcampy i projekty zdalne dla organizacji międzynarodowych. Każdy program ma własne kryteria. Sprawdź kartę projektu, kraj, organizacje wysyłającą i przyjmującą, daty, kwalifikacje oraz język. Poproś o wykaz kosztów, zasad rozliczeń i wsparcia udzielanego podczas pobytu."},{"heading":"Jak zastosować ją w praktyce","text":"Ustal kontakt do mentora, dojazd, zakwaterowanie, zakres ubezpieczenia, sposób zgłoszenia krzywdzenia oraz warunki wcześniejszego zakończenia. Sprawdź oficjalne komunikaty podróżne i aktualne wymagania kraju. Przy zadaniach z dziećmi zweryfikuj, jak organizacja dobiera kandydatów, nadzoruje kontakt i zapewnia ciągłość wsparcia."},{"heading":"Co ustalić na dyżurze","text":"Zapytaj, kto określił lokalną potrzebę i kto przejmie zadania po Twoim wyjeździe. Przygotuj listę pytań do osób odpowiedzialnych w obu organizacjach. Porównaj obciążenie czasowe z alternatywą lokalną lub zdalną. Przed wyjazdem zapisz kontakty i ustal, jak przekazywać pracę i zgłaszać trudności."},{"heading":"Co zrobić krok po kroku","text":"1. Porównaj oficjalne opisy ofert.\n2. Potwierdź koszty, miejsce, ubezpieczenie i opiekę.\n3. Sprawdź drogę zgłoszenia i plan powrotu.\n4. Uzgodnij przekazanie pracy osobie na miejscu."},{"heading":"Sytuacja z dyżuru","text":"Płatna oferta obiecuje kilkudniowy samodzielny kontakt z dziećmi bez weryfikacji kandydatów i prowadzącej osoby na miejscu."},{"heading":"Przećwicz","text":"Porównaj zadania, koszty, ubezpieczenie, mentora, dostępność i drogę zgłoszenia incydentu w dwóch ofertach."},{"heading":"Sprawdź wynik po wykonaniu","text":"Wstrzymaj decyzję. Poproś o standardy ochrony, zasady weryfikacji, nadzór i uzasadnienie roli. Wybierz ofertę z potwierdzonymi warunkami ochrony.\n\nKryterium ćwiczenia. Odróżniasz potwierdzone warunki od pytań otwartych i wskazujesz warunki decyzji."}],"learning":{"intro":"Porównać oferty wyjazdowe według roli, wsparcia, kosztów i ryzyka.","situation":"Płatna oferta obiecuje kilkudniowy samodzielny kontakt z dziećmi bez weryfikacji kandydatów i prowadzącej osoby na miejscu.","example":"Wstrzymaj decyzję. Poproś o standardy ochrony, zasady weryfikacji, nadzór i uzasadnienie roli. Wybierz ofertę z potwierdzonymi warunkami ochrony.","task":"Porównaj zadania, koszty, ubezpieczenie, mentora, dostępność i drogę zgłoszenia incydentu w dwóch ofertach.","question":"Co wymaga wyjaśnienia przed wyjazdem?","options":["Kolor koszulki zespołu","Liczba zdjęć w ogłoszeniu","Brak informacji o ubezpieczeniu i osobie do kontaktu"],"correct":2,"explanation":"Ochrona i wsparcie wpływają na bezpieczeństwo całego udziału."},"references":[{"title":"Europejski Korpus Solidarności – wolontariat w Europie i poza nią","url":"https://europa.eu/youreurope/citizens/education/volunteering/index_pl.htm"},{"title":"Szkolenia i wsparcie uczestników – Europejski Portal Młodzieżowy","url":"https://youth.europa.eu/solidarity/young-people/training-support"},{"title":"United Nations Volunteers – ścieżki wolontariatu","url":"https://www.unv.org/become-volunteer/"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"}]}},
{"lesson_no":36,"title_pl":"Przeciążenie i przerwa w wolontariacie","material":{"module":10,"sections":[{"heading":"Cel lekcji","text":"Rozpoznać przeciążenie i uzgodnić zmianę obciążenia."},{"heading":"Najważniejsza zasada","text":"Regularne odsuwanie odpoczynku, rozdrażnienie po dyżurze, gorsza koncentracja i poczucie przymusu są powodami do rozmowy. Zwróć uwagę, czy obciążenie narasta przy konkretnej czynności, samotnych zmianach lub w czasie innych zobowiązań. Ustal własny limit i datę jego przeglądu."},{"heading":"Jak zastosować ją w praktyce","text":"Poproś o krótsze zmiany, pracę w parze, inną rolę, przerwę lub rozmowę z przygotowaną osobą. Przegląd operacyjny może objąć fakty i organizację zadania. Rozmowa o osobistych przeżyciach pozostaje dobrowolna. Gdy cierpienie utrudnia codzienne funkcjonowanie lub się utrzymuje, skorzystaj z pomocy odpowiedniego specjalisty."},{"heading":"Co ustalić na dyżurze","text":"Zgłoś brak dostępności możliwie wcześnie i uzgodnij przekazanie spraw. Jeśli problemem jest brak zastępstw, długie zmiany lub stała presja, opisz je jako kwestię organizacji pracy. Zapytaj, kto podejmie decyzję i kiedy zespół sprawdzi, czy zmiana pomogła."},{"heading":"Co zrobić krok po kroku","text":"1. Zauważ sygnały i ich związek z obciążeniem.\n2. Powiedz o limicie i zaproponuj zmianę.\n3. Przekaż sprawy wymagające ciągłości.\n4. Ustal warunki oraz termin rozmowy o powrocie."},{"heading":"Sytuacja z dyżuru","text":"Po trzech długich zmianach popełniasz pomyłki w wydawaniu paczek. Zespół prosi o jeszcze jeden dyżur."},{"heading":"Przećwicz","text":"Napisz plan przerwy z dwoma sygnałami przeciążenia, limitem dyżurów i kontaktem do wspierającej osoby."},{"heading":"Sprawdź wynik po wykonaniu","text":"Powiedz to wprost. „Potrzebuję przerwy. Mogę dziś opisać stan magazynu i przekazać go zastępcy”. Ustal, kto odbierze przekazanie.\n\nKryterium ćwiczenia. Plan wskazuje obserwowalne sygnały, termin rozmowy i sposób przekazania."}],"learning":{"intro":"Rozpoznać przeciążenie i uzgodnić zmianę obciążenia.","situation":"Po trzech długich zmianach popełniasz pomyłki w wydawaniu paczek. Zespół prosi o jeszcze jeden dyżur.","example":"Powiedz to wprost. „Potrzebuję przerwy. Mogę dziś opisać stan magazynu i przekazać go zastępcy”. Ustal, kto odbierze przekazanie.","task":"Napisz plan przerwy z dwoma sygnałami przeciążenia, limitem dyżurów i kontaktem do wspierającej osoby.","question":"Regularnie popełniasz błędy z przemęczenia. Co robisz?","options":["Zgłaszam problem i uzgadniam przerwę albo zmianę grafiku","Ukrywam błędy do końca projektu","Biorę dodatkowe dyżury"],"correct":0,"explanation":"Zmiana obciążenia oraz przekazanie spraw ograniczają dalsze pomyłki."},"references":[{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Wolontariat i aktywność społeczna w Polsce 2020–2024 – synteza NIW","url":"https://niw.gov.pl/wp-content/uploads/2026/05/Wolontariat-i-aktywnosc-spoleczna-w-Polsce-2020-2024.pdf"},{"title":"Wsparcie Organizacji Wolontariatu – WOW w NGO!, NIW","url":"https://niw.gov.pl/nasze-programy/korpus-solidarnosci/wsparcie-organizacji-wolontariatu-w-ngo-wow-w-ngo/"},{"title":"Keeping volunteers – NCVO","url":"https://www.ncvo.org.uk/help-and-guidance/involving-volunteers/supporting-and-managing-volunteers/keeping-volunteers/"}]}},
{"lesson_no":37,"title_pl":"Jakość działania i ocena efektów","material":{"module":10,"sections":[{"heading":"Cel lekcji","text":"Sprawdzić, czy wsparcie osiągnęło rezultat uzgodniony z uczestnikiem."},{"heading":"Najważniejsza zasada","text":"Liczba godzin i paczek opisuje skalę działania. Osobno zaplanuj, jak sprawdzisz rezultat, którego oczekuje odbiorca. Przy pomocy komputerowej wskaźnikiem wykonania jest liczba spotkań, a rezultatem umiejętność samodzielnego zapisania i odnalezienia dokumentu. Uzgodnij kryterium z uczestnikiem i organizacją."},{"heading":"Jak zastosować ją w praktyce","text":"Ogranicz zbieranie danych do potrzeb działania. Do podsumowania często wystarczy zagregowana opinia, liczba spotkań i uwaga o barierze. Uczestnik może odmówić udziału w wywiadzie lub fotografii. Powinien wiedzieć, gdzie może zgłosić uwagę i jaki sposób jest dla niego dostępny."},{"heading":"Co ustalić na dyżurze","text":"Przekaż zespołowi zaobserwowany fakt, kwestię do sprawdzenia i propozycję małego testu. Przykładowo możesz zaproponować późniejszy dyżur dla osób, które nie docierają przed piętnastą, a po miesiącu porównać frekwencję. Weź pod uwagę, że na wynik mogą wpływać również pora roku, dostępność transportu czy termin wydarzeń."},{"heading":"Co zrobić krok po kroku","text":"1. Zapisz działanie i rezultat.\n2. Ustal minimalny zakres potrzebnych informacji.\n3. Zbierz dobrowolną informację zwrotną.\n4. Uzgodnij zmianę, odpowiedzialną osobę i termin przeglądu."},{"heading":"Sytuacja z dyżuru","text":"Sponsor pyta, czy po szkoleniu dziesięć osób potrafi już samodzielnie wykonać zadanie."},{"heading":"Przećwicz","text":"Zapisz jeden wskaźnik pracy, jeden rezultat i pytanie do uczestnika swojej roli."},{"heading":"Sprawdź wynik po wykonaniu","text":"Podaj frekwencję i opisz plan krótkiej próby samodzielnego wykonania. Przekaż wynik w niezbędnym zakresie, bez ujawniania danych uczestników.\n\nKryterium ćwiczenia. Każdą miarę da się sprawdzić bez zbędnego gromadzenia danych."}],"learning":{"intro":"Sprawdzić, czy wsparcie osiągnęło rezultat uzgodniony z uczestnikiem.","situation":"Sponsor pyta, czy po szkoleniu dziesięć osób potrafi już samodzielnie wykonać zadanie.","example":"Podaj frekwencję i opisz plan krótkiej próby samodzielnego wykonania. Przekaż wynik w niezbędnym zakresie, bez ujawniania danych uczestników.","task":"Zapisz jeden wskaźnik pracy, jeden rezultat i pytanie do uczestnika swojej roli.","question":"Która obserwacja pokazuje rezultat szkolenia z orientacji w bibliotece?","options":["Liczba ulotek","Uczestnik sam wskazuje dział i znajduje książkę","Liczba godzin na dyżurze"],"correct":1,"explanation":"Samodzielna próba sprawdza umiejętność, którą szkolenie miało rozwinąć."},"references":[{"title":"CDC Quality Training Standards","url":"https://www.cdc.gov/training-development/php/qts/"},{"title":"Zgłaszanie naruszeń ochrony danych – Urząd Ochrony Danych Osobowych","url":"https://uodo.gov.pl/pl/525/2584"},{"title":"Wolontariat i aktywność społeczna w Polsce 2020–2024 – synteza NIW","url":"https://niw.gov.pl/wp-content/uploads/2026/05/Wolontariat-i-aktywnosc-spoleczna-w-Polsce-2020-2024.pdf"}]}},
{"lesson_no":38,"title_pl":"Przekazanie roli i zakończenie współpracy","material":{"module":10,"sections":[{"heading":"Cel lekcji","text":"Zamknąć współpracę z przekazaniem spraw, sprzętu i dostępów."},{"heading":"Najważniejsza zasada","text":"Sprawdź warunki rozwiązania porozumienia i powiadom koordynatora możliwie wcześnie. Ustal ostatnią zmianę, sposób poinformowania uczestników i osobę przejmującą zadania. W bezpośrednim zagrożeniu przerwij działanie. Formalności dokończ później z bezpiecznego miejsca."},{"heading":"Jak zastosować ją w praktyce","text":"Spisz otwarte zadania wraz z terminami i wskaż, gdzie są zatwierdzone dokumenty. Przekazuj dane uprawnionym osobom wyznaczonym kanałem. Zwróć identyfikator, klucze i sprzęt. Potwierdź zamknięcie dostępów i postępuj zgodnie z zasadami organizacji przy lokalnych kopiach."},{"heading":"Co ustalić na dyżurze","text":"Możesz wystąpić do korzystającego o pisemne zaświadczenie o wykonanych świadczeniach, w tym o ich zakresie. Jeśli potrzebujesz opinii, możesz o nią poprosić. Organizator może ją wydać. W informacji zwrotnej opisz warunek, który wspierał Twoją pracę, przeszkodę i konkretną zmianę potrzebną kolejnej osobie."},{"heading":"Co zrobić krok po kroku","text":"1. Ustal ostatni dzień i osobę przejmującą.\n2. Przekaż terminy i otwarte sprawy bez zbędnych danych.\n3. Zwróć sprzęt i zamknij dostępy.\n4. W razie potrzeby wystąp o zaświadczenie."},{"heading":"Sytuacja z dyżuru","text":"Kończysz wolontariat zdalny. Kolejna osoba prosi o wysłanie prywatnej kopii danych przez komunikator."},{"heading":"Przećwicz","text":"Stwórz listę zamknięcia roli z rubryką potwierdzenia przekazania."},{"heading":"Sprawdź wynik po wykonaniu","text":"Wskaż zatwierdzone miejsce i osobę nadającą dostęp. Zgłoś prywatną kopię i wykonaj instrukcję jej bezpiecznego usunięcia lub zabezpieczenia.\n\nKryterium ćwiczenia. Uwzględniasz zadania, odbiorcę, terminy, dane, sprzęt, dostępy i dokumenty."}],"learning":{"intro":"Zamknąć współpracę z przekazaniem spraw, sprzętu i dostępów.","situation":"Kończysz wolontariat zdalny. Kolejna osoba prosi o wysłanie prywatnej kopii danych przez komunikator.","example":"Wskaż zatwierdzone miejsce i osobę nadającą dostęp. Zgłoś prywatną kopię i wykonaj instrukcję jej bezpiecznego usunięcia lub zabezpieczenia.","task":"Stwórz listę zamknięcia roli z rubryką potwierdzenia przekazania.","question":"Co korzystający wydaje na żądanie wolontariusza?","options":["Umowę o pracę","Pozytywną opinię w każdym przypadku","Pisemne zaświadczenie o wykonaniu świadczeń i ich zakresie"],"correct":2,"explanation":"Art. 44 przewiduje obowiązkowe zaświadczenie na żądanie i fakultatywną opinię."},"references":[{"title":"Ustawa o działalności pożytku publicznego i o wolontariacie","url":"https://eli.gov.pl/api/acts/DU/2025/1338/text/U/D20251338Lj.pdf"},{"title":"Zgłaszanie naruszeń ochrony danych – Urząd Ochrony Danych Osobowych","url":"https://uodo.gov.pl/pl/525/2584"},{"title":"Praktyczny poradnik współpracy z wolontariuszami – Fundacja Stocznia","url":"https://stocznia.org.pl/publikacje/praktyczny-poradnik-wspolpracy-z-wolontariuszami/"}]}},
{"lesson_no":39,"title_pl":"Sprawdzian praktyczny i plan na 30 dni","material":{"module":10,"sections":[{"heading":"Cel lekcji","text":"Przećwiczyć trzy kluczowe decyzje i ułożyć plan pierwszego miesiąca."},{"heading":"Najważniejsza zasada","text":"Zacznij od symulacji z osobą, która udzieli Ci informacji zwrotnej. Przyjmij dyżur i powtórz zakres. Odegraj sytuację, w której ktoś naciska na przekroczenie granicy. Następnie opisz reakcję na zagrożenie i wypełnij próbne zgłoszenie fikcyjnymi danymi. Rozmowę z dyspozytorem przećwicz bez łączenia się z 112."},{"heading":"Jak zastosować ją w praktyce","text":"Osoba obserwująca ocenia widoczne zachowania. Przyznaje 0 punktów za pominięcie albo działanie ryzykowne, 1 za wykonanie po podpowiedzi i 2 za samodzielne wykonanie. Ocena obejmuje zakres roli, granicę, przerwanie zagrożenia, przekazanie właściwej osobie i zapis faktów. Powtórz scenariusz po omówieniu błędu."},{"heading":"Co ustalić na dyżurze","text":"W planie 30 dni zapisz terminy wyboru roli, uzgodnienia zakresu, wdrożenia, pierwszego dyżuru i rozmowy z opiekunem. Dopasuj tempo do swoich możliwości i wymagań organizacji. Wymagane szkolenia, weryfikacja i zgoda osoby prowadzącej mają pierwszeństwo przed datami z planu."},{"heading":"Co zrobić krok po kroku","text":"1. Odegraj przyjęcie dyżuru i spokojną odmowę.\n2. Przećwicz wycofanie, wezwanie pomocy i przekazanie faktów.\n3. Rozwiąż test i powtórz trudną sytuację.\n4. Zapisz pierwsze kroki, terminy i kontakt do opiekuna."},{"heading":"Sytuacja z dyżuru","text":"W symulacji mówisz spokojnie, ale nadal próbujesz rozmawiać mimo utraty bezpiecznej drogi wyjścia."},{"heading":"Przećwicz","text":"Zrób sprawdzian, użyj karty planu i po tygodniu powtórz wybraną scenkę bez podpowiedzi."},{"heading":"Sprawdź wynik po wykonaniu","text":"Powtórz scenę od momentu wzrostu ryzyka. Przerwij rozmowę wcześniej, wycofaj się, gdy możesz to zrobić bezpiecznie, i przećwicz wezwanie pomocy z lokalizacją i opisem zagrożenia.\n\nKryterium ćwiczenia. Zdobądź 9/12 w teście i wszystkie decyzje krytyczne. W symulacji dąż do 8/10 i samodzielnego przerwania kontaktu w zagrożeniu."}],"learning":{"intro":"Przećwiczyć trzy kluczowe decyzje i ułożyć plan pierwszego miesiąca.","situation":"W symulacji mówisz spokojnie, ale nadal próbujesz rozmawiać mimo utraty bezpiecznej drogi wyjścia.","example":"Powtórz scenę od momentu wzrostu ryzyka. Przerwij rozmowę wcześniej, wycofaj się, gdy możesz to zrobić bezpiecznie, i przećwicz wezwanie pomocy z lokalizacją i opisem zagrożenia.","task":"Zrób sprawdzian, użyj karty planu i po tygodniu powtórz wybraną scenkę bez podpowiedzi.","question":"Co pozwala ocenić gotowość do bezpiecznego dyżuru?","options":["Decyzje w scenariuszu, wdrożenie i kontakt do wsparcia","Samo przeczytanie kursu","Liczba godzin otwarcia strony"],"correct":0,"explanation":"Scenka sprawdza decyzje, a wdrożenie przekłada je na konkretne miejsce."},"references":[{"title":"CDC Quality Training Standards","url":"https://www.cdc.gov/training-development/php/qts/"},{"title":"Standardy bezpieczeństwa i dobrostanu wolontariuszy – IFRC","url":"https://www.ifrc.org/document/implementation-guide-standards-facilitate-safety-security-and-well-being-volunteers"},{"title":"Numer alarmowy 112 – jak zgłaszać zdarzenie","url":"https://www.gov.pl/web/numer-alarmowy-112/jak-zglaszac"},{"title":"Praktyczny poradnik współpracy z wolontariuszami – Fundacja Stocznia","url":"https://stocznia.org.pl/publikacje/praktyczny-poradnik-wspolpracy-z-wolontariuszami/"}]}}
]$volunteer$::jsonb)
  as lesson(lesson_no smallint, title_pl text, material jsonb)
on conflict (course_slug, lesson_no) do update set
  title_pl = excluded.title_pl,
  material = excluded.material,
  updated_at = now()
where (ta_lessons.title_pl, ta_lessons.material)
  is distinct from (excluded.title_pl, excluded.material);

commit;
